# --------------------------------------------------------------- tableaux

class Tableau:
    """A tableau, given by its rows.

    EXAMPLES::

        sage: T = Tableau([[1,2,2], [2,3]]); T
        [[1, 2, 2], [2, 3]]
        sage: T.shape(), T.to_word()
        ([3, 2], word: 23122)
    """

    def __init__(self, rows):
        self._rows = [list(r) for r in rows]

    def __repr__(self):
        return repr(self._rows)

    def __eq__(self, other):
        if isinstance(other, Tableau):
            return self._rows == other._rows
        if isinstance(other, list):
            return self._rows == other
        return NotImplemented

    def __ne__(self, other):
        return not self == other

    def __hash__(self):
        return hash(tuple(tuple(r) for r in self._rows))

    def __iter__(self):
        return iter(self._rows)

    def __getitem__(self, i):
        return self._rows[i]

    def __len__(self):
        return len(self._rows)

    def shape(self):
        """The shape (row lengths).

        EXAMPLES::

            sage: Tableau([[1, 2, 5], [3, 4]]).shape()
            [3, 2]
        """
        return [len(r) for r in self._rows]

    def size(self):
        """The number of boxes.

        EXAMPLES::

            sage: Tableau([[1, 2, 5], [3, 4]]).size()
            5
        """
        return sum(len(r) for r in self._rows)

    def to_word(self):
        """The row reading word (rows from the bottom up).

        EXAMPLES::

            sage: Tableau([[1, 2, 5], [3, 4]]).to_word()
            word: 34125
        """
        return Word([x for r in reversed(self._rows) for x in r])

    def to_list(self):
        """The rows, as lists.

        EXAMPLES::

            sage: Tableau([[1, 2], [3]]).to_list()
            [[1, 2], [3]]
        """
        return [list(r) for r in self._rows]

    def conjugate(self):
        """The transpose.

        EXAMPLES::

            sage: Tableau([[1, 2, 5], [3, 4]]).conjugate()
            [[1, 3], [2, 4], [5]]
        """
        n = len(self._rows[0]) if self._rows else 0
        return Tableau([[r[j] for r in self._rows if j < len(r)] for j in range(n)])

    def schuetzenberger_involution(self, n=None):
        """The Schuetzenberger involution (evacuation) for entries in 1..n.

        EXAMPLES::

            sage: Tableau([[1, 2], [3]]).schuetzenberger_involution(n=4)
            [[2, 4], [3]]
        """
        w = self.to_word()
        if n is None:
            n = max(w) if w else 0
        w = [n + 1 - x for x in reversed(w)]
        return _rsk_insert(w)

    def is_semistandard(self):
        """Whether rows weakly increase and columns strictly increase.

        EXAMPLES::

            sage: Tableau([[1, 1], [2]]).is_semistandard(), Tableau([[1, 1], [1]]).is_semistandard()
            (True, False)
        """
        r = self._rows
        return all(r[i][j] <= r[i][j + 1] for i in range(len(r)) for j in range(len(r[i]) - 1)) and \
            all(r[i][j] < r[i + 1][j] for i in range(len(r) - 1) for j in range(len(r[i + 1])))


class Word:
    """A finite word (printed as Sage prints words).

    EXAMPLES::

        sage: Word([3, 1, 2]), Word([10, 2])
        (word: 312, word: 10,2)
    """

    def __init__(self, letters):
        self._w = list(letters)

    def __repr__(self):
        ls = [str(x) for x in self._w]
        return "word: " + ("".join(ls) if all(len(x) == 1 for x in ls) else ",".join(ls))

    def __iter__(self):
        return iter(self._w)

    def __len__(self):
        return len(self._w)

    def __getitem__(self, k):
        return self._w[k]

    def __eq__(self, other):
        if isinstance(other, Word):
            return self._w == other._w
        return self._w == list(other) if isinstance(other, (list, tuple)) else NotImplemented

    def __hash__(self):
        return hash(tuple(self._w))

    def __reversed__(self):
        return reversed(self._w)

    def length(self):
        """The length.

        EXAMPLES::

            sage: Word([3, 1, 2]).length()
            3
        """
        return len(self._w)


def _rsk_insert(word):
    rows = []
    for x in word:
        for r in rows:
            k = next((j for j, y in enumerate(r) if y > x), None)
            if k is None:
                r.append(x)
                break
            r[k], x = x, r[k]
        else:
            rows.append([x])
    return Tableau(rows)


# ------------------------------------------------------- generic crystals

class CrystalElement:
    """An element of a crystal.

    EXAMPLES::

        sage: B = crystals.Tableaux("A2", shape=[2,1]); b = B[0]; b, b.f(1), b.weight()
        ([[1, 1], [2]], [[1, 2], [2]], (2, 1, 0))
    """

    def parent(self):
        """The crystal.

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[0].parent()
            The crystal of tableaux of type ['A', 2] and shape(s) [[2, 1]]
        """
        return self._P

    # subclasses implement _e(i), _f(i), epsilon(i), phi(i), _wt(), _key()

    def e(self, i):
        """The raising operator e_i (None if undefined).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[1].e(1), B[1].e(2)
            ([[1, 1], [2]], None)
        """
        return self._e(i)

    def f(self, i):
        """The lowering operator f_i (None if undefined).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[0].f(1), B[0].f(1).f(1)
            ([[1, 2], [2]], None)
        """
        return self._f(i)

    def __eq__(self, other):
        # elements of different crystals (Letters A2 and B2) differ
        return type(self) is type(other) and self._key() == other._key() and \
            (self._P is other._P or repr(self._P) == repr(other._P))

    def __ne__(self, other):
        return not self == other

    def __hash__(self):
        return hash(self._key())

    def __lt__(self, other):
        try:
            return self._P._index(self) < self._P._index(other)
        except (NotImplementedError, KeyError):
            return repr(self) < repr(other)

    def weight(self):
        """The weight (in the weight lattice realization).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[3].weight()
            (1, 0, 2)
        """
        return self._P._realize(self._wt())

    def e_string(self, ls):
        """Apply e_i for i in the list (None if undefined).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[4].e_string([1, 2])
            [[1, 3], [2]]
        """
        b = self
        for i in ls:
            b = b.e(i)
            if b is None:
                return None
        return b

    def f_string(self, ls):
        """Apply f_i for i in the list (None if undefined).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[0].f_string([1, 2, 2])
            [[1, 3], [3]]
        """
        b = self
        for i in ls:
            b = b.f(i)
            if b is None:
                return None
        return b

    def is_highest_weight(self, index_set=None):
        """Whether e_i is undefined for all i (in the index set).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[0].is_highest_weight(), B[1].is_highest_weight(), B[1].is_highest_weight(index_set=[2])
            (True, False, True)
        """
        I = index_set if index_set is not None else self._P.index_set()
        return all(self.epsilon(i) == 0 for i in I)

    def is_lowest_weight(self, index_set=None):
        """Whether f_i is undefined for all i (in the index set).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[4].is_lowest_weight()
            True
        """
        I = index_set if index_set is not None else self._P.index_set()
        return all(self.phi(i) == 0 for i in I)

    def to_highest_weight(self, index_set=None):
        """(highest weight element, the list of i applied).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[4].to_highest_weight()
            [[[1, 1], [2]], [1, 2, 2, 1]]
        """
        I = index_set if index_set is not None else self._P.index_set()
        b, path = self, []
        while True:
            for i in I:
                c = b.e(i)
                if c is not None:
                    b = c
                    path.append(i)
                    break
            else:
                return [b, path]

    def to_lowest_weight(self, index_set=None):
        """(lowest weight element, the list of i applied).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[0].to_lowest_weight()
            [[[2, 3], [3]], [1, 2, 2, 1]]
        """
        I = index_set if index_set is not None else self._P.index_set()
        b, path = self, []
        while True:
            for i in I:
                c = b.f(i)
                if c is not None:
                    b = c
                    path.append(i)
                    break
            else:
                return [b, path]

    def Epsilon(self):
        """sum_i epsilon_i Lambda_i.

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[1].Epsilon()
            (1, 0, 0)
        """
        L = self._P._Lambda()
        return sum((self.epsilon(i) * L[i] for i in self._P.index_set()), L[self._P.index_set()[0]] * 0)

    def Phi(self):
        """sum_i phi_i Lambda_i.

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B[0].Phi()
            (2, 1, 0)
        """
        L = self._P._Lambda()
        return sum((self.phi(i) * L[i] for i in self._P.index_set()), L[self._P.index_set()[0]] * 0)

    def lusztig_involution(self):
        """The Lusztig involution (on the connected component).

        EXAMPLES::

            sage: B = crystals.Tableaux(['A',3], shape=[2,1]); b = B(rows=[[1,2],[3]])
            sage: b.lusztig_involution()
            [[2, 4], [3]]
        """
        hw, path = self.to_highest_weight()
        lw = hw.to_lowest_weight()[0]
        sigma = _star(self._P.cartan_type())
        b = lw
        for i in reversed(path):
            b = b.e(sigma.get(i, i))
        return b

    def __pos__(self):
        return self


def _star(ct):
    """The diagram automorphism -w0 on the index set."""
    out, off = {}, 0
    for c in ct.component_types():
        l, n = c._letter, c._n
        m = {}
        if l == "A":
            m = {i: n + 1 - i for i in range(1, n + 1)}
        elif l == "D" and n % 2 == 1:
            m = {n - 1: n, n: n - 1}
        elif l == "E" and n == 6:
            m = {1: 6, 6: 1, 3: 5, 5: 3}
        for i in range(1, n + 1):
            out[off + i] = off + m.get(i, i) if ct._components else m.get(i, i)
        off += n
    return out


class Crystal:
    """A crystal: elements generated from module generators by the f_i (or
    an explicit list), with weights in a realization.

    EXAMPLES::

        sage: B = crystals.Tableaux("A2", shape=[2,1]); B
        The crystal of tableaux of type ['A', 2] and shape(s) [[2, 1]]
        sage: B.cardinality(), B.index_set()
        (8, (1, 2))
    """

    _repr = "A crystal"

    def __repr__(self):
        return self._repr

    def cartan_type(self):
        """The Cartan type.

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B.cartan_type()
            ['A', 2]
        """
        return self._ct

    def index_set(self):
        """The index set.

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B.index_set()
            (1, 2)
        """
        return tuple(self._ct.index_set())

    def weight_lattice_realization(self):
        """The ambient space in which the weights live.

        EXAMPLES::

            sage: crystals.Tableaux("A2", shape=[2,1]).weight_lattice_realization()
            Ambient space of the Root system of type ['A', 2]
        """
        return self._space

    def _realize(self, v):
        if isinstance(self._space, _lie.WeightLattice):
            return _lie.AffineWeight(self._space, v)
        return _lie.AmbientVector(self._space, v)

    def _Lambda(self):
        return self._space.fundamental_weights()

    def Lambda(self):
        """The fundamental weights.

        EXAMPLES::

            sage: crystals.Tableaux(['A',2], shape=[2,1]).Lambda()
            Finite family {1: (1, 0, 0), 2: (1, 1, 0)}
        """
        return self._Lambda()

    def _children(self, b):
        out = []
        for i in self.index_set():
            c = b.f(i)
            if c is not None and _first_e(c, self.index_set()) == i:
                out.append(c)
        return out

    def _elements(self):
        if getattr(self, "_cache", None) is None:
            if hasattr(self, "_explicit"):
                self._cache = self._explicit()
            else:
                out = []
                stack = list(reversed(self.module_generators))
                while stack:
                    b = stack.pop()
                    out.append(b)
                    stack.extend(reversed(self._children(b)))
                self._cache = out
            self._pos = {b: k for k, b in enumerate(self._cache)}
        return self._cache

    def _index(self, b):
        self._elements()
        return self._pos[b]

    def __iter__(self):
        return iter(self._elements())

    def list(self):
        """The elements, in Sage's order.

        EXAMPLES::

            sage: C = crystals.Letters("A2"); C.list()
            [1, 2, 3]
        """
        return list(self._elements())

    def __getitem__(self, k):
        return self._elements()[k]

    def __len__(self):
        return len(self._elements())

    def __contains__(self, b):
        return b in self._elements()

    def cardinality(self):
        """The number of elements.

        EXAMPLES::

            sage: crystals.Spins("B3").cardinality()
            8
        """
        return _sa().Integer(len(self._elements()))

    def is_finite(self):
        """Whether the crystal is finite.

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B.is_finite()
            True
        """
        return True

    def an_element(self):
        """An element (the first module generator).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B.an_element()
            [[1, 1], [2]]
        """
        return self.module_generators[0]

    def highest_weight_vector(self):
        """The highest weight vector (of a connected crystal).

        EXAMPLES::

            sage: crystals.Tableaux("A2", shape=[2,1]).highest_weight_vector()
            [[1, 1], [2]]
        """
        h = self.highest_weight_vectors()
        if len(h) != 1:
            raise RuntimeError("the crystal is not connected")
        return h[0]

    def highest_weight_vectors(self):
        """The highest weight vectors.

        EXAMPLES::

            sage: C = crystals.Letters("A2"); T = crystals.TensorProduct(C,C,C)
            sage: T.highest_weight_vectors()
            ([1, 1, 1], [2, 1, 1], [1, 2, 1], [3, 2, 1])
        """
        return tuple(b for b in self if b.is_highest_weight())

    def lowest_weight_vectors(self):
        """The lowest weight vectors.

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); B.lowest_weight_vectors()
            ([[2, 3], [3]],)
        """
        return tuple(b for b in self if b.is_lowest_weight())

    def character(self, R=None):
        """The character, in the Weyl character ring R.

        EXAMPLES::

            sage: A2 = WeylCharacterRing("A2"); C = crystals.Letters("A2"); T = crystals.TensorProduct(C,C,C)
            sage: T.character(A2)
            A2(1,1,1) + 2*A2(2,1,0) + A2(3,0,0)
        """
        if R is None:
            R = _lie.WeylCharacterRing(self._ct)
        w = {}
        for b in self:
            v = b._wt()
            w[v] = w.get(v, 0) + 1
        return R.char_from_weights({_lie.AmbientVector(R._space, v): m for v, m in w.items()})

    def digraph(self, subset=None, index_set=None):
        """The crystal graph (edges b -> f_i(b) labelled i).

        EXAMPLES::

            sage: crystals.Letters("A2").digraph()
            Digraph on 3 vertices
        """
        I = index_set if index_set is not None else self.index_set()
        S = list(subset) if subset is not None else self.list()
        Sset = set(S)
        G = _sa().DiGraph()
        for b in S:
            G.add_vertex(b)
        for b in S:
            for i in I:
                c = b.f(i)
                if c is not None and c in Sset:
                    G.add_edge(b, c, i)
        return G

    def plot(self, **options):
        """The crystal graph, plotted.

        EXAMPLES::

            sage: crystals.Letters("A2").plot()
            Graphics object consisting of 8 graphics primitives
        """
        G = self.digraph()
        return G.plot(edge_labels=True, **options)

    def latex_file(self, filename):
        """Write a LaTeX file of the crystal graph (a stub here).

        EXAMPLES::

            sage: B = crystals.Tableaux("A2", shape=[2,1]); fn = tmp_filename(ext='.tex'); B.latex_file(fn)
        """
        open(filename, "w").write("% crystal graph\n")

    def subcrystal(self, index_set=None, generators=None, max_depth=None, direction="both", contained=None):
        """The elements reachable from the generators by e_i and f_i for i
        in the index set.

        EXAMPLES::

            sage: B = crystals.Tableaux(['A',2], shape=[2,1])
            sage: len(B.subcrystal(index_set=[1], generators=[B[0]]))
            2
        """
        I = index_set if index_set is not None else self.index_set()
        gens = list(generators) if generators is not None else list(self.module_generators)
        if contained is not None:
            inside = contained if callable(contained) else (lambda b, S=contained: b in S)
        else:
            inside = lambda b: True
        gens = [b for b in gens if inside(b)]
        seen = set(gens)
        out = list(gens)
        level = list(gens)
        depth = 0
        while level and (max_depth is None or depth < max_depth):
            nxt = []
            for b in level:
                for i in I:
                    for c in ([b.f(i)] if direction in ("both", "lower") else []) + ([b.e(i)] if direction in ("both", "upper") else []):
                        if c is not None and c not in seen and inside(c):
                            seen.add(c)
                            out.append(c)
                            nxt.append(c)
            level = nxt
            depth += 1
        return out

    def crystal_morphism(self, on_gens, **kwds):
        """The crystal morphism with the given images of the highest weight
        elements (a dict).

        EXAMPLES::

            sage: C = crystals.Letters('A2'); B = crystals.Tableaux('A2', shape=[1])
            sage: Psi = C.crystal_morphism({C(1): B[0]}); [Psi(x) for x in C]
            [[[1]], [[2]], [[3]]]
        """
        return crystal_morphism(self, on_gens)

    def connected_components_generators(self):
        """The highest weight vectors of the components.

        EXAMPLES::

            sage: C = crystals.Letters("A2"); crystals.TensorProduct(C, C).connected_components_generators()
            ([1, 1], [2, 1])
        """
        return self.highest_weight_vectors()


def _first_e(b, I):
    for i in I:
        if b.epsilon(i) > 0:
            return i
    return None


# -------------------------------------------------------- letters and spins

class _LetterElement(CrystalElement):
    __slots__ = ("_P", "_v")

    def __init__(self, P, v):
        self._P, self._v = P, v

    def _key(self):
        return self._v

    def __repr__(self):
        return repr(self._v) if not isinstance(self._v, int) else str(self._v)

    def value(self):
        """The letter.

        EXAMPLES::

            sage: crystals.Letters("D3")(-3).value()
            -3
        """
        return self._v

    def _e(self, i):
        v = self._P._einv[i].get(self._v)
        return None if v is None else self._P._el(v)

    def _f(self, i):
        v = self._P._fmap[i].get(self._v)
        return None if v is None else self._P._el(v)

    def epsilon(self, i):
        """epsilon_i (the length of the i-string above).

        EXAMPLES::

            sage: C = crystals.Letters("B2"); C(0).epsilon(2), C(-2).epsilon(2)
            (1, 2)
        """
        k, v = 0, self._v
        E = self._P._einv[i]
        while v in E:
            v = E[v]
            k += 1
        return _sa().Integer(k)

    def phi(self, i):
        """phi_i (the length of the i-string below).

        EXAMPLES::

            sage: C = crystals.Letters("B2"); C(2).phi(2), C(0).phi(2)
            (2, 1)
        """
        k, v = 0, self._v
        Fm = self._P._fmap[i]
        while v in Fm:
            v = Fm[v]
            k += 1
        return _sa().Integer(k)

    def _wt(self):
        return self._P._wts[self._v]


class CrystalOfLetters(Crystal):
    """The crystal of letters (the crystal of the standard representation;
    for E6 and E7 the minuscule 27 and 56).

    EXAMPLES::

        sage: crystals.Letters("C3"), crystals.Letters("C3").list()
        (The crystal of letters for type ['C', 3], [1, 2, 3, -3, -2, -1])
    """

    def __init__(self, ct, dual=False):
        self._ct = ct
        self._dual = dual
        self._space = RootSystem_(ct).ambient_space()
        self._repr = "The crystal of letters for type %r" % (ct,) + (" (dual)" if dual else "")
        l, n = ct._letter, ct._n
        d = _data(ct).dim
        fm = {i: {} for i in ct.index_set()}
        wts = {}
        if l in "ABCD":
            if l == "A":
                letters = list(range(1, n + 2))
            elif l == "B":
                letters = list(range(1, n + 1)) + [0] + list(range(-n, 0))
            else:
                letters = list(range(1, n + 1)) + list(range(-n, 0))
            for x in letters:
                wts[x] = _zero(d) if x == 0 else _e(d, (abs(x) - 1, 1 if x > 0 else -1))
            for i in range(1, n + 1):
                if l == "A" or i < n:
                    fm[i][i] = i + 1
                    if l != "A":
                        fm[i][-(i + 1)] = -i
            if l == "B":
                fm[n][n] = 0
                fm[n][0] = -n
            elif l == "C":
                fm[n][n] = -n
            elif l == "D":
                fm[n][n - 1] = -n
                fm[n][n] = -(n - 1)
        elif l == "G":
            letters = [1, 2, 3, 0, -3, -2, -1]
            W = {1: (1, 0, -1), 2: (1, -1, 0), 3: (0, 1, -1), 0: (0, 0, 0)}
            for x in letters:
                wts[x] = tuple(_F(a) for a in W[x]) if x >= 0 else _neg(tuple(_F(a) for a in W[-x]))
            fm[1] = {1: 2, 3: 0, 0: -3, -2: -1}
            fm[2] = {2: 3, -3: -2}
        elif l == "E" and n in (6, 7):
            D = _data(ct)
            top = (D.fw[5] if dual else D.fw[0]) if n == 6 else D.fw[6]
            letters, seen = [], {}
            stack = [top]
            lab = lambda w: _elabel(D, w)
            order = []
            while stack:
                w = stack.pop()
                if w in seen:
                    continue
                seen[w] = lab(w)
                order.append(w)
                for k, (a, c) in enumerate(zip(D.simple, D.coroots)):
                    if _dot(w, c) == 1:
                        stack.append(_subv(w, a))
            for w in order:
                wts[seen[w]] = w
            for k, (a, c) in enumerate(zip(D.simple, D.coroots)):
                i = D.I[k]
                for w in order:
                    if _dot(w, c) == 1:
                        fm[i][seen[w]] = seen[_subv(w, a)]
            letters = None
            self._top = seen[top]
        else:
            raise NotImplementedError("crystal of letters of type %r" % (ct,))
        self._fmap = fm
        self._einv = {i: {v: k for k, v in fm[i].items()} for i in fm}
        self._wts = wts
        self._letters = letters
        self.module_generators = (self._el(letters[0] if letters else self._top),)

    def _el(self, v):
        return _LetterElement(self, v)

    def __call__(self, v):
        """The letter with the given value.

        EXAMPLES::

            sage: C = crystals.Letters("B2"); C(0), C(-1).weight()
            (0, (-1, 0))
        """
        if isinstance(v, _LetterElement):
            return v
        if isinstance(v, (list, tuple)):
            v = tuple(int(a) for a in v)
        else:
            v = int(v)
        if v not in self._wts:
            raise ValueError("%r is not a letter" % (v,))
        return self._el(v)

    def __eq__(self, other):
        return isinstance(other, CrystalOfLetters) and self._ct == other._ct

    def __hash__(self):
        return hash(("letters", self._ct))


def _elabel(D, w):
    neg = sorted((D.I[k] for k, c in enumerate(D.coroots) if _dot(w, c) == -1))
    pos = sorted((D.I[k] for k, c in enumerate(D.coroots) if _dot(w, c) == 1))
    return tuple([-i for i in neg] + pos)


class _SpinElement(CrystalElement):
    __slots__ = ("_P", "_v")

    def __init__(self, P, v):
        self._P, self._v = P, v

    def _key(self):
        return self._v

    def __repr__(self):
        return "".join("+" if s > 0 else "-" for s in self._v)

    def signature(self):
        """The signs.

        EXAMPLES::

            sage: crystals.Spins("B3")[3].signature()
            '-++'
        """
        return repr(self)

    def _e(self, i):
        v = self._P._op(self._v, i, False)
        return None if v is None else _SpinElement(self._P, v)

    def _f(self, i):
        v = self._P._op(self._v, i, True)
        return None if v is None else _SpinElement(self._P, v)

    def epsilon(self, i):
        """epsilon_i.

        EXAMPLES::

            sage: C = crystals.Spins("B2"); C("+-").epsilon(2), C("--").epsilon(2)
            (1, 1)
        """
        return _sa().Integer(int(self._P._op(self._v, i, False) is not None))

    def phi(self, i):
        """phi_i.

        EXAMPLES::

            sage: C = crystals.Spins("B2"); C("++").phi(1), C("++").phi(2)
            (0, 1)
        """
        return _sa().Integer(int(self._P._op(self._v, i, True) is not None))

    def _wt(self):
        return tuple(_F(s, 2) for s in self._v)


class CrystalOfSpins(Crystal):
    """The crystal of spins of type B_n, or the plus/minus spins of type D_n.

    EXAMPLES::

        sage: C = crystals.Spins("B2"); C, C.list()
        (The crystal of spins for type ['B', 2], [++, +-, -+, --])
    """

    def __init__(self, ct, kind):
        self._ct, self._kind = ct, kind
        self._space = RootSystem_(ct).ambient_space()
        n = ct._n
        name = {"B": "The crystal of spins", "plus": "The plus crystal of spins", "minus": "The minus crystal of spins"}[kind]
        self._repr = "%s for type %r" % (name, ct)
        top = tuple([1] * n) if kind != "minus" else tuple([1] * (n - 1) + [-1])
        self.module_generators = (_SpinElement(self, top),)

    def _op(self, v, i, lower):
        n = self._ct._n
        v = list(v)
        a, b = (1, -1) if lower else (-1, 1)
        if i < n:
            if v[i - 1] == a and v[i] == b:
                v[i - 1], v[i] = b, a
                return tuple(v)
            return None
        if self._kind == "B":
            if v[n - 1] == a:
                v[n - 1] = b
                return tuple(v)
            return None
        if v[n - 2] == a and v[n - 1] == a:
            v[n - 2] = v[n - 1] = b
            return tuple(v)
        return None

    def __call__(self, v):
        """The spin with the given signs.

        EXAMPLES::

            sage: C = crystals.Spins("B2"); C("+-").f(2)
        """
        if isinstance(v, _SpinElement):
            return v
        if isinstance(v, str):
            v = [1 if c == "+" else -1 for c in v]
        return _SpinElement(self, tuple(int(a) for a in v))


# ---------------------------------------------------------- tensor products

def _signature(factors, i):
    """Sage's (anti-Kashiwara) signature rule: (index of the factor f_i acts
    on or None, index for e_i or None, epsilon, phi)."""
    eps = [b.epsilon(i) for b in factors]
    phs = [b.phi(i) for b in factors]
    if any(isinstance(x, float) for x in eps + phs):
        return _signature_general(factors, i, eps, phs)
    plus, minus = [], []
    for j in range(len(factors) - 1, -1, -1):
        b = factors[j]
        for _ in range(int(b.epsilon(i))):
            if plus:
                plus.pop()
            else:
                minus.append(j)
        for _ in range(int(b.phi(i))):
            plus.append(j)
    return (plus[0] if plus else None), (minus[-1] if minus else None), len(minus), len(plus)


def _signature_general(factors, i, eps, phs):
    """The tensor product rule from epsilon, phi and <wt, h_i> (also for
    crystals that are not seminormal, such as T_lambda)."""
    N = len(factors)
    c = list(range(N - 1, -1, -1))     # Kashiwara order: b_N (x) ... (x) b_1
    E = [None] * N
    Ph = [None] * N
    hi = []
    for j in c:
        b = factors[j]
        e, p = eps[j], phs[j]
        h = (p - e) if not (isinstance(e, float) or isinstance(p, float)) else b._hi(i)
        hi.append(h)
    # prefix values over the Kashiwara order
    pe, pp, ph = None, None, 0
    for t, j in enumerate(c):
        e, p, h = eps[j], phs[j], hi[t]
        if t == 0:
            pe, pp, ph = e, p, h
        else:
            pe, pp = max(pe, e - ph), max(p, pp + h)
            ph = ph + h
        E[t], Ph[t] = pe, pp

    def where(lower):
        t = N - 1
        while t > 0:
            j = c[t]
            go_left = Ph[t - 1] > eps[j] if lower else Ph[t - 1] >= eps[j]
            if go_left:
                t -= 1
            else:
                return j
        return c[0]
    # the chosen factor's own e_i / f_i decide (they may be undefined)
    return where(True), where(False), E[N - 1], Ph[N - 1]


class TensorProductElement(CrystalElement):
    """

    EXAMPLES::

        sage: C = crystals.Letters("A2"); T = crystals.TensorProduct(C, C); b = T(C(1), C(2)); b, b.f(1), b.e(1)
        ([1, 2], [2, 2], [1, 1])
    """
    __slots__ = ("_P", "_f_")

    def __init__(self, P, factors):
        self._P, self._f_ = P, tuple(factors)

    def _key(self):
        return tuple(b._key() for b in self._f_)

    def __repr__(self):
        return "[" + ", ".join(repr(b) for b in self._f_) + "]"

    def __iter__(self):
        return iter(self._f_)

    def __getitem__(self, k):
        return self._f_[k]

    def __len__(self):
        return len(self._f_)

    def _e(self, i):
        j = _signature(self._f_, i)[1]
        if j is None:
            return None
        fs = list(self._f_)
        fs[j] = fs[j].e(i)
        if fs[j] is None:
            return None
        return TensorProductElement(self._P, fs)

    def _f(self, i):
        j = _signature(self._f_, i)[0]
        if j is None:
            return None
        fs = list(self._f_)
        fs[j] = fs[j].f(i)
        if fs[j] is None:
            return None
        return TensorProductElement(self._P, fs)

    def epsilon(self, i):
        """epsilon_i (by the signature rule).

        EXAMPLES::

            sage: C = crystals.Letters("A2"); T = crystals.TensorProduct(C, C); T(C(1), C(2)).epsilon(1), T(C(2), C(1)).epsilon(1)
            (1, 0)
        """
        x = _signature(self._f_, i)[2]
        return x if isinstance(x, float) else _sa().Integer(x)

    def phi(self, i):
        """phi_i (by the signature rule).

        EXAMPLES::

            sage: C = crystals.Letters("A2"); T = crystals.TensorProduct(C, C); T(C(1), C(2)).phi(1), T(C(2), C(1)).phi(1)
            (1, 0)
        """
        x = _signature(self._f_, i)[3]
        return x if isinstance(x, float) else _sa().Integer(x)

    def _hi(self, i):
        return sum(b._hi(i) if hasattr(b, "_hi") else b.phi(i) - b.epsilon(i) for b in self._f_)

    def _wt(self):
        w = None
        for b in self._f_:
            v = b._wt()
            w = v if w is None else _addv(w, v)
        return w


class TensorProductOfCrystals(Crystal):
    """The tensor product of crystals (all of it, or the part generated by
    given elements).

    EXAMPLES::

        sage: C = crystals.Letters("A2"); T = crystals.TensorProduct(C, C); T
        Full tensor product of the crystals [The crystal of letters for type ['A', 2], The crystal of letters for type ['A', 2]]
        sage: T.list()
        [[1, 1], [1, 2], [1, 3], [2, 1], [2, 2], [2, 3], [3, 1], [3, 2], [3, 3]]
    """

    def __init__(self, crystals, generators=None):
        self._crystals = list(crystals)
        self._ct = self._crystals[0]._ct
        self._space = self._crystals[0]._space
        names = "[" + ", ".join(repr(c) for c in self._crystals) + "]"
        if generators is None:
            self._repr = "Full tensor product of the crystals " + names
            self._full = True
        else:
            self._repr = "The tensor product of the crystals " + names
            self._full = False
            self.module_generators = tuple(self(*g) if not isinstance(g, TensorProductElement) else g for g in generators)

    def crystals(self):
        """The factors.

        EXAMPLES::

            sage: C = crystals.Letters("A2"); crystals.TensorProduct(C, C).crystals()
            [The crystal of letters for type ['A', 2], The crystal of letters for type ['A', 2]]
        """
        return list(self._crystals)

    def _explicit_full(self):
        import itertools
        out = []
        for t in itertools.product(*[c.list() for c in self._crystals]):
            out.append(TensorProductElement(self, t))
        return out

    def _elements(self):
        if self._full and getattr(self, "_cache", None) is None:
            self._cache = self._explicit_full()
            self._pos = {b: k for k, b in enumerate(self._cache)}
        return Crystal._elements(self)

    def __call__(self, *args):
        """The element with the given factors.

        EXAMPLES::

            sage: C = crystals.Letters("A2"); T = crystals.TensorProduct(C, C); T(C(3), C(1))
            [3, 1]
        """
        if len(args) == 1 and isinstance(args[0], (list, tuple)):
            args = args[0]
        return TensorProductElement(self, [c(a) if not isinstance(a, CrystalElement) else a for c, a in zip(self._crystals, args)])

    def highest_weight_vectors(self):
        """The highest weight vectors.

        EXAMPLES::

            sage: C = crystals.Letters("A2"); crystals.TensorProduct(C, C).highest_weight_vectors()
            ([1, 1], [2, 1])
        """
        if not self._full:
            return Crystal.highest_weight_vectors(self)
        cs = self._crystals
        if len(cs) == 1:
            return tuple(TensorProductElement(self, [b]) for b in cs[0].highest_weight_vectors())
        tail = TensorProductOfCrystals(cs[1:])
        out = []
        for h in tail.highest_weight_vectors():
            for x in cs[0]:
                b = TensorProductElement(self, [x] + list(h._f_))
                if b.is_highest_weight():
                    out.append(b)
        return tuple(out)

    def cardinality(self):
        """The number of elements.

        EXAMPLES::

            sage: C = crystals.Letters("A2"); crystals.TensorProduct(C, C, C).cardinality()
            27
        """
        if self._full:
            r = 1
            for c in self._crystals:
                r *= int(c.cardinality())
            return _sa().Integer(r)
        return Crystal.cardinality(self)


def TensorProduct(*crystals, **options):
    """The tensor product of crystals (Sage's anti-Kashiwara convention).

    EXAMPLES::

        sage: C = crystals.Letters("A2"); T = crystals.TensorProduct(C,C,C); T.cardinality()
        27
        sage: T = crystals.TensorProduct(C, C, generators=[[C(2), C(1)]]); T.list()
        [[2, 1], [3, 1], [3, 2]]
    """
    return TensorProductOfCrystals(crystals, options.get("generators"))


# ------------------------------------------------------- crystals of tableaux

class _TableauElement(CrystalElement):
    """A Kashiwara-Nakashima tableau: a word of letters (column reading,
    columns left to right, each from the bottom up), possibly with a spin."""

    __slots__ = ("_P", "_shape", "_w", "_spin")

    def __init__(self, P, shape, word, spin=None):
        self._P, self._shape, self._w, self._spin = P, tuple(shape), tuple(word), spin

    def _key(self):
        return (self._shape, tuple(b._v for b in self._w), self._spin._v if self._spin is not None else None)

    def _factors(self):
        return ([self._spin] if self._spin is not None else []) + list(self._w)

    def _rows(self):
        cols = _col_lengths(self._shape)
        rows = [[] for _ in range(len(self._shape))]
        k = 0
        for c in cols:
            col = [self._w[k + t]._v for t in range(c)]
            k += c
            for r, x in enumerate(reversed(col)):
                rows[r].append(x)
        return [r for r in rows if r]

    def __repr__(self):
        t = repr(self._rows())
        if self._spin is not None:
            return "[%r, %s]" % (self._spin, t)
        return t

    def to_tableau(self):
        """The tableau.

        EXAMPLES::

            sage: B = crystals.Tableaux(['A',3], shape=[2,1]); B[1].to_tableau()
            [[1, 2], [2]]
        """
        return Tableau(self._rows())

    def __iter__(self):
        return iter([b._v for b in self._w])

    def _new(self, fs):
        if self._spin is not None:
            return _TableauElement(self._P, self._shape, fs[1:], fs[0])
        return _TableauElement(self._P, self._shape, fs)

    def _e(self, i):
        fs = self._factors()
        j = _signature(fs, i)[1]
        if j is None:
            return None
        fs[j] = fs[j].e(i)
        if fs[j] is None:
            return None
        return self._new(fs)

    def _f(self, i):
        fs = self._factors()
        j = _signature(fs, i)[0]
        if j is None:
            return None
        fs[j] = fs[j].f(i)
        if fs[j] is None:
            return None
        return self._new(fs)

    def epsilon(self, i):
        return _sa().Integer(_signature(self._factors(), i)[2])

    def phi(self, i):
        return _sa().Integer(_signature(self._factors(), i)[3])

    def _wt(self):
        w = _zero(_data(self._P._ct).dim)
        for b in self._factors():
            w = _addv(w, b._wt())
        return w

    def shape(self):
        return list(self._shape)


def _col_lengths(shape):
    shape = [int(x) for x in shape if x]
    if not shape:
        return []
    return [sum(1 for r in shape if r > j) for j in range(shape[0])]


class CrystalOfTableaux(Crystal):
    """The crystal of (Kashiwara-Nakashima) tableaux of given shape(s).

    EXAMPLES::

        sage: B = crystals.Tableaux(["C",2], shape=[1,1]); B
        The crystal of tableaux of type ['C', 2] and shape(s) [[1, 1]]
        sage: B.list()
        [[[1], [2]], [[1], [-2]], [[2], [-2]], [[2], [-1]], [[-2], [-1]]]
    """

    def __init__(self, ct, shapes):
        self._ct = ct
        self._space = RootSystem_(ct).ambient_space()
        self._letters = CrystalOfLetters(ct)
        self._shapes = [[_q(x) for x in s] for s in shapes]
        sh = ", ".join("[" + ", ".join(_fs(x) for x in s) + "]" for s in self._shapes)
        self._repr = "The crystal of tableaux of type %r and shape(s) [%s]" % (ct, sh)
        self.module_generators = tuple(self._hw(s) for s in self._shapes)

    def _hw(self, shape):
        l, n = self._ct._letter, self._ct._n
        spin = None
        sh = list(shape)
        if any(x.denominator == 2 for x in sh):
            sh = sh + [_F(0)] * (n - len(sh))
            if l == "B":
                spin = CrystalOfSpins(self._ct, "B").module_generators[0]
            elif l == "D":
                spin = CrystalOfSpins(self._ct, "minus" if sh[-1] < 0 else "plus").module_generators[0]
            sh = [abs(x) - _F(1, 2) for x in sh]
        sh = [int(x) for x in sh if x]
        cols = _col_lengths(sh)
        word = []
        for c in cols:
            word += [self._letters(k) for k in range(c, 0, -1)]
        return _TableauElement(self, sh, word, spin)

    def __call__(self, *args, **kwds):
        """The tableau with the given rows (or columns).

        EXAMPLES::

            sage: B = crystals.Tableaux(["A",3], shape=[2,1]); B(rows=[[1,2],[3]]), B(columns=[[1,3],[2]])
            ([[1, 2], [3]], [[1, 2], [3]])
        """
        rows = kwds.get("rows")
        if rows is None and "columns" in kwds:
            cols = kwds["columns"]
            word = []
            for c in cols:
                word += [self._letters(x) for x in reversed(c)]
            sh = [sum(1 for c in cols if len(c) > r) for r in range(max(len(c) for c in cols))]
            return _TableauElement(self, sh, word)
        if rows is None and args:
            rows = args[0]
            if isinstance(rows, (_TableauElement,)):
                return rows
        sh = [len(r) for r in rows]
        word = []
        for j in range(len(rows[0]) if rows else 0):
            col = [rows[r][j] for r in range(len(rows)) if j < len(rows[r])]
            word += [self._letters(x) for x in reversed(col)]
        g = self.module_generators[0]
        return _TableauElement(self, sh, word, g._spin)

    def shapes(self):
        """The shapes.

        EXAMPLES::

            sage: crystals.Tableaux("A2", shapes=[[2,1],[1]]).shapes()
            [[Fraction(2, 1), Fraction(1, 1)], [Fraction(1, 1)]]
        """
        return [list(s) for s in self._shapes]


def Tableaux(ct, shape=None, shapes=None):
    """The crystal of tableaux of a classical type (or G2) and shape(s).

    EXAMPLES::

        sage: B = crystals.Tableaux("A2", shape=[2,1]); B
        The crystal of tableaux of type ['A', 2] and shape(s) [[2, 1]]
        sage: B.list()
        [[[1, 1], [2]], [[1, 2], [2]], [[1, 3], [2]], [[1, 3], [3]], [[2, 3], [3]], [[1, 1], [3]], [[1, 2], [3]], [[2, 2], [3]]]
        sage: crystals.Tableaux(['B',2], shape=[3/2,1/2]).cardinality()
        16
    """
    ct = CartanType(ct)
    if shapes is None:
        shapes = [shape]
    return CrystalOfTableaux(ct, shapes)


def Letters(ct, element_print_style=None, dual=None):
    """The crystal of letters.

    EXAMPLES::

        sage: C = crystals.Letters("B2"); C, C.list()
        (The crystal of letters for type ['B', 2], [1, 2, 0, -2, -1])
        sage: crystals.Letters("E6").list()[:5]
        [(1,), (-1, 3), (-3, 4), (-4, 2, 5), (-2, 5)]
    """
    return CrystalOfLetters(CartanType(ct), bool(dual))


def Spins(ct):
    """The crystal of spins of type B.

    EXAMPLES::

        sage: crystals.Spins("B3").list()
        [+++, ++-, +-+, -++, +--, -+-, --+, ---]
    """
    return CrystalOfSpins(CartanType(ct), "B")


def SpinsPlus(ct):
    """The plus crystal of spins of type D.

    EXAMPLES::

        sage: crystals.SpinsPlus("D4").list()
        [++++, ++--, +-+-, -++-, +--+, -+-+, --++, ----]
    """
    return CrystalOfSpins(CartanType(ct), "plus")


def SpinsMinus(ct):
    """The minus crystal of spins of type D.

    EXAMPLES::

        sage: crystals.SpinsMinus("D4")[0].weight()
        (1/2, 1/2, 1/2, -1/2)
    """
    return CrystalOfSpins(CartanType(ct), "minus")


class _FastRankTwo(CrystalOfTableaux):
    def __init__(self, ct, shape):
        CrystalOfTableaux.__init__(self, ct, [shape])
        self._repr = "The fast crystal for %s with shape [%s]" % (ct._short(), ",".join(_fs(_q(x)) for x in shape))


def FastRankTwo(ct, shapes=None, shape=None, format=None):
    """The crystal of tableaux of a rank two type (as Sage's fast crystal).

    EXAMPLES::

        sage: B = crystals.FastRankTwo(['B',2], shape=[3/2,1/2]); B
        The fast crystal for B2 with shape [3/2,1/2]
        sage: B.highest_weight_vector().weight()
        (3/2, 1/2)
    """
    return _FastRankTwo(CartanType(ct), shape if shape is not None else shapes[0])


def HighestWeight(dominant_weight, model=None):
    """The highest weight crystal B(lambda) of a finite type.

    EXAMPLES::

        sage: La = CartanType(['E',6]).root_system().weight_lattice().fundamental_weights()
        sage: T = crystals.HighestWeight(La[1]); t = T[4]; t
        [(-2, 5)]
        sage: t.lusztig_involution()
        [(-3, 2)]
    """
    w = dominant_weight
    P = w._P
    ct = P._ct
    I = list(ct.index_set())
    c = {i: int(w._v[k]) for k, i in enumerate(I)}
    l = ct._letter
    if l in "ABCDG" and ct.is_irreducible():
        D = _data(ct)
        v = _zero(D.dim)
        for k, i in enumerate(I):
            v = _addv(v, _smul(c[i], D.fw[k]))
        return _HW(Tableaux(ct, shape=list(v)), dominant_weight)
    if l == "E" and ct._n in (6, 7):
        top = 1 if ct._n == 6 else 7
        if ct._n == 6 and c[6] and all(c[i] == 0 for i in I if i != 6):
            top = 6
        if all(c[i] == 0 for i in I if i != top):
            L = Letters(ct, dual=(top == 6))
            T = TensorProductOfCrystals([L] * c[top], generators=[[L.module_generators[0]] * c[top]])
            T._repr = "Finite dimensional highest weight crystal of type %r and highest weight %r" % (ct, dominant_weight)
            return T
    raise NotImplementedError("highest weight crystals of type %r and weight %r" % (ct, dominant_weight))


def _HW(B, la):
    B._repr = "Finite dimensional highest weight crystal of type %r and highest weight %r" % (B._ct, la)
    return B


# --------------------------------------------- Kirillov-Reshetikhin (type A)

class _KRElement(CrystalElement):
    __slots__ = ("_P", "_b")

    def __init__(self, P, b):
        self._P, self._b = P, b

    def _key(self):
        return self._b._key()

    def __repr__(self):
        return repr(self._b)

    def lift(self):
        """The element of the classical crystal."""
        return self._b

    def _e(self, i):
        if i == 0:
            K = self._P
            c = K._pr(self._b).e(1)
            return None if c is None else _KRElement(K, K._pr_inv(c))
        c = self._b.e(i)
        return None if c is None else _KRElement(self._P, c)

    def _f(self, i):
        if i == 0:
            K = self._P
            c = K._pr(self._b).f(1)
            return None if c is None else _KRElement(K, K._pr_inv(c))
        c = self._b.f(i)
        return None if c is None else _KRElement(self._P, c)

    def epsilon(self, i):
        if i == 0:
            return self._P._pr(self._b).epsilon(1)
        return self._b.epsilon(i)

    def phi(self, i):
        if i == 0:
            return self._P._pr(self._b).phi(1)
        return self._b.phi(i)

    def weight(self):
        K = self._P
        WL = K._WL
        n = K._ct._n
        v = [self.phi(i) - self.epsilon(i) for i in range(0, n + 1)]
        return _lie.AffineWeight(WL, [_F(int(x)) for x in v] + [_F(0)])

    def _wt(self):
        return self._b._wt()

    def Phi(self):
        L = self._P._WL.fundamental_weights()
        return sum((self.phi(i) * L[i] for i in self._P.index_set()), self._P._WL.zero())

    def Epsilon(self):
        L = self._P._WL.fundamental_weights()
        return sum((self.epsilon(i) * L[i] for i in self._P.index_set()), self._P._WL.zero())


class KirillovReshetikhinTypeA(Crystal):
    """The Kirillov-Reshetikhin crystal B^{r,s} of type A_n^(1): rectangular
    tableaux, with e_0, f_0 by promotion.

    EXAMPLES::

        sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); K
        Kirillov-Reshetikhin crystal of type ['A', 3, 1] with (r,s)=(2,1)
        sage: [b.f(0) for b in K]
        [None, None, None, None, [[1], [2]], [[1], [3]]]
    """

    def __init__(self, ct, r, s):
        self._ct, self._r, self._s = ct, r, s
        n = ct._n
        self._classical = Tableaux(CartanType("A%d" % n), shape=[s] * r)
        self._space = self._classical._space
        self._WL = _lie.WeightLattice(RootSystem_(ct), True)
        self._repr = "Kirillov-Reshetikhin crystal of type %r with (r,s)=(%d,%d)" % (ct, r, s)
        self.module_generators = (_KRElement(self, self._classical.module_generators[0]),)

    def index_set(self):
        """The index set 0, ..., n.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); K.index_set()
            (0, 1, 2, 3)
        """
        return tuple(range(0, self._ct._n + 1))

    def _children(self, b):
        # the classical crystal order
        return []

    def _elements(self):
        if getattr(self, "_cache", None) is None:
            self._cache = [_KRElement(self, b) for b in self._classical]
            self._pos = {b: k for k, b in enumerate(self._cache)}
        return self._cache

    def classical_decomposition(self):
        """The classical crystal.

        EXAMPLES::

            sage: crystals.KirillovReshetikhin(['A',3,1], 2, 1).classical_decomposition()
            The crystal of tableaux of type ['A', 3] and shape(s) [[1, 1]]
        """
        return self._classical

    def module_generator(self):
        """The classical highest weight element.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); K.module_generator()
            [[1], [2]]
        """
        return self.module_generators[0]

    def weight_lattice_realization(self):
        """The extended weight lattice.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); K.weight_lattice_realization()
            Extended weight lattice of the Root system of type ['A', 3, 1]
        """
        return self._WL

    def _Lambda(self):
        return self._WL.fundamental_weights()

    def __call__(self, *args, **kwds):
        """The element with the given rows.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); K(rows=[[1],[3]])
            [[1], [3]]
        """
        return _KRElement(self, self._classical(*args, **kwds))

    def retract(self, b):
        """The element of K with the given classical element.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); b = crystals.Tableaux(['A',3], shape=[1,1])(rows=[[1],[3]]); K.retract(b)
            [[1], [3]]
        """
        return _KRElement(self, b)

    def _pr(self, b):
        return _promotion(self._classical, b, True)

    def _pr_inv(self, b):
        return _promotion(self._classical, b, False)

    def promotion(self):
        """Promotion (on the classical crystal).

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(['A',3,1], 2, 1); b = K.module_generator()
            sage: K.promotion()(b.lift())
            [[2], [3]]
        """
        return lambda b: _promotion(self._classical, b, True)

    def promotion_inverse(self):
        """Inverse promotion (on the classical crystal).

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); b = K.module_generator().lift(); K.promotion_inverse()(K.promotion()(b)) == b
            True
        """
        return lambda b: _promotion(self._classical, b, False)

    def cardinality(self):
        """The number of elements.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["A",3,1], 2, 1); K.cardinality()
            6
        """
        return self._classical.cardinality()


def _promotion(C, b, forward):
    """Schuetzenberger promotion on rectangular tableaux with entries 1..n+1:
    remove the largest letters, slide, add one, fill with 1 (forward); or
    the inverse."""
    n1 = C._ct._n + 1
    rows = [list(r) for r in b._rows()]
    R, S = len(rows), len(rows[0])
    if forward:
        cells = [[x for x in r] for r in rows]
        # remove n+1 (they sit at the ends of rows); slide the rest to the bottom right
        T = [[(x if x != n1 else None) for x in r] for r in cells]
        T = _slide_to_corner(T, True)
        rows = [[(1 if x is None else x + 1) for x in r] for r in T]
    else:
        T = [[(x if x != 1 else None) for x in r] for r in rows]
        T = _slide_to_corner(T, False)
        rows = [[(n1 if x is None else x - 1) for x in r] for r in T]
    return C(rows=rows)


def _slide_to_corner(T, down):
    """Jeu de taquin: move the holes (None) of a rectangle to the top left
    (down=True: entries slide down/right) or to the bottom right."""
    R, S = len(T), len(T[0])
    T = [r[:] for r in T]
    if down:
        while True:
            # the hole furthest down-right that has a non-hole after it
            holes = [(i, j) for i in range(R) for j in range(S) if T[i][j] is None]
            moved = False
            for (i, j) in sorted(holes, reverse=True):
                cand = []
                if i > 0 and T[i - 1][j] is not None:
                    cand.append((T[i - 1][j], i - 1, j))
                if j > 0 and T[i][j - 1] is not None:
                    cand.append((T[i][j - 1], i, j - 1))
                if cand:
                    # slide the larger neighbour into the hole (ties: from above)
                    m = max(c[0] for c in cand)
                    c = [c for c in cand if c[0] == m][0]
                    T[i][j], T[c[1]][c[2]] = c[0], None
                    moved = True
                    break
            if not moved:
                return T
    else:
        while True:
            holes = [(i, j) for i in range(R) for j in range(S) if T[i][j] is None]
            moved = False
            for (i, j) in sorted(holes):
                cand = []
                if i + 1 < R and T[i + 1][j] is not None:
                    cand.append((T[i + 1][j], i + 1, j))
                if j + 1 < S and T[i][j + 1] is not None:
                    cand.append((T[i][j + 1], i, j + 1))
                if cand:
                    m = min(c[0] for c in cand)
                    c = [c for c in cand if c[0] == m][0]
                    T[i][j], T[c[1]][c[2]] = c[0], None
                    moved = True
                    break
            if not moved:
                return T


def _kr_shapes(ct, r, s):
    """(classical type, shapes) of the classical decomposition of B^{r,s}."""
    l, n = ct._letter, ct._n
    import itertools
    def boxes(r, s, step, horizontal):
        # Sage's order: by the reversed vector of row (or column) lengths
        out = []
        if horizontal:
            for rows in itertools.product(range(s, -1, -step), repeat=r):
                if list(rows) == sorted(rows, reverse=True):
                    out.append((tuple(reversed(rows)), [x for x in rows if x]))
        else:
            for cols in itertools.product(range(r, -1, -step), repeat=s):
                if list(cols) == sorted(cols, reverse=True):
                    lam = [sum(1 for c in cols if c > i) for i in range(r)]
                    out.append((tuple(reversed(cols)), [x for x in lam if x]))
        return [lam for _, lam in sorted(out)]
    spin = lambda k, sign: [[_F(k, 2)] * (n - 1) + [_F(sign * k, 2)]]
    if ct._letter == "BC" and not ct._dual:
        return CartanType("C%d" % n), boxes(r, s, 1, True)
    if ct._letter == "BC" and ct._dual:
        return CartanType("B%d" % n), boxes(r, s, 2, True)
    if ct._dual:
        # twisted types: A_{2n-1}^(2) (B~*), D_{n+1}^(2) (C~*), E_6^(2) (F~*)
        if l == "B":
            return CartanType("C%d" % n), boxes(r, s, 2, False)
        if l == "C":
            cl = CartanType("B%d" % n)
            if r == n:
                return cl, spin(s, 1)
            return cl, boxes(r, s, 1, True)
        raise NotImplementedError("Kirillov-Reshetikhin crystals of type %r" % (ct,))
    cl = CartanType("%s%d" % (l, n))
    if l == "D":
        if r == n:
            return cl, spin(s, 1)
        if r == n - 1:
            return cl, spin(s, -1)
        return cl, boxes(r, s, 2, False)
    if l == "B":
        if r == n:
            return cl, [[_F(s, 2)] * n]
        return cl, boxes(r, s, 2, False)
    if l == "C":
        if r == n:
            return cl, [[s] * n]
        return cl, boxes(r, s, 2, True)
    raise NotImplementedError("Kirillov-Reshetikhin crystals of type %r" % (ct,))


class KirillovReshetikhinGeneric(Crystal):
    """A Kirillov-Reshetikhin crystal B^{r,s} (its classical crystal; the
    0-arrows are not available).

    EXAMPLES::

        sage: K = crystals.KirillovReshetikhin(["D",4,1], 2, 1); K
        Kirillov-Reshetikhin crystal of type ['D', 4, 1] with (r,s)=(2,1)
        sage: K.cardinality()
        29
    """

    def __init__(self, ct, r, s):
        self._ct, self._r, self._s = ct, r, s
        self._repr = "Kirillov-Reshetikhin crystal of type %r with (r,s)=(%d,%d)" % (ct, r, s)
        self._WL = _lie.WeightLattice(RootSystem_(ct), True)
        if ct._letter == "E":
            la = _lie.WeightLattice(RootSystem_(CartanType("E%d" % ct._n)), False).fundamental_weights()
            if (ct._n, r) in ((6, 1), (6, 6), (7, 7)):
                self._classical = HighestWeight(la[r])
                self._dec = "Direct sum of the crystals Family (%r,)" % (self._classical,)
            elif (ct._n, r) == (6, 2):
                z = _lie.WeightLattice(RootSystem_(CartanType("E6")), False).zero()
                self._classical = None
                self._dec = "Direct sum of the crystals Family (Finite dimensional highest weight crystal of type ['E', 6] and highest weight 0,\nFinite dimensional highest weight crystal of type ['E', 6] and highest weight Lambda[2])"
            else:
                raise NotImplementedError("Kirillov-Reshetikhin crystals of type %r" % (ct,))
        else:
            cl, shapes = _kr_shapes(ct, r, s)
            self._classical = Tableaux(cl, shapes=shapes)
            self._dec = None
        self._space = self._classical._space if self._classical is not None else None
        if self._classical is not None:
            gens = self._classical.module_generators
            self.module_generators = (_KRElement(self, gens[-1]),)

    def index_set(self):
        """The (affine) index set.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["D",4,1], 2, 1); K.index_set()
            (0, 1, 2, 3, 4)
        """
        return tuple(self._ct.index_set())

    def classical_decomposition(self):
        """The classical decomposition.

        EXAMPLES::

            sage: crystals.KirillovReshetikhin(['C',3,1], 2, 4).classical_decomposition()
            The crystal of tableaux of type ['C', 3] and shape(s) [[], [2], [4], [2, 2], [4, 2], [4, 4]]
            sage: crystals.KirillovReshetikhin(['D',4,1], 3, 1).classical_decomposition()
            The crystal of tableaux of type ['D', 4] and shape(s) [[1/2, 1/2, 1/2, -1/2]]
        """
        if self._dec is not None:
            return _Named(self._dec)
        return self._classical

    def _elements(self):
        if getattr(self, "_cache", None) is None:
            self._cache = [_KRElement(self, b) for b in self._classical]
            self._pos = {b: k for k, b in enumerate(self._cache)}
        return self._cache

    def module_generator(self):
        """The highest weight element of the largest component.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["D",4,1], 2, 1); K.module_generator()
            [[1], [2]]
        """
        return self.module_generators[0]

    def weight_lattice_realization(self):
        """The extended weight lattice.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["D",4,1], 2, 1); K.weight_lattice_realization()
            Extended weight lattice of the Root system of type ['D', 4, 1]
        """
        return self._WL

    def _Lambda(self):
        return self._WL.fundamental_weights()

    def __call__(self, *args, **kwds):
        """An element of the classical crystal.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["D",4,1], 2, 1); K(rows=[[2],[-2]])
            [[2], [-2]]
        """
        return _KRElement(self, self._classical(*args, **kwds))

    def retract(self, b):
        """The element of K with the given classical element.

        EXAMPLES::

            sage: K = crystals.KirillovReshetikhin(["D",4,1], 2, 1); b = K.classical_decomposition()[0]; K.retract(b)
            []
        """
        return _KRElement(self, b)

    def _pr(self, b):
        raise NotImplementedError("the 0-arrows of Kirillov-Reshetikhin crystals of type %r are not available in sagebrush yet" % (self._ct,))

    _pr_inv = _pr

    def ambient_crystal(self):
        """The ambient crystal (for C_n^(1), A_2n^(2) and D_n+1^(2)).

        EXAMPLES::

            sage: crystals.KirillovReshetikhin(['C',3,1], 1, 2).ambient_crystal()
            Kirillov-Reshetikhin crystal of type ['B', 4, 1]^* with (r,s)=(1,2)
        """
        ct, n = self._ct, self._ct._n
        if ct._letter == "C" and not ct._dual:
            return KirillovReshetikhinGeneric(CartanType(["A", 2 * n + 1, 2]), self._r, self._s)
        return KirillovReshetikhinGeneric(CartanType("C%d~" % n), self._r, 2 * self._s)


def KirillovReshetikhin(ct, r, s, model=None):
    """The Kirillov-Reshetikhin crystal B^{r,s} (type A_n^(1)).

    EXAMPLES::

        sage: K = crystals.KirillovReshetikhin(['A',3,1], 1, 1); K.list()
        [[[1]], [[2]], [[3]], [[4]]]
        sage: K = crystals.KirillovReshetikhin(['A',3,1], 2, 1); b = K.module_generator(); b
        [[1], [2]]
        sage: b.e(0), b.f(0), b.weight()
        ([[2], [4]], None, -Lambda[0] + Lambda[2])
    """
    ct = CartanType(ct)
    if ct._letter == "A" and ct._affine and not ct._dual:
        return KirillovReshetikhinTypeA(ct, int(r), int(s))
    return KirillovReshetikhinGeneric(ct, int(r), int(s))




# ------------------------------------------------------ elementary crystals

_INF = float("inf")


def _weight_parts(la):
    """(realization, coordinate tuple, pairing function i -> <la, h_i>)."""
    if isinstance(la, _lie.AmbientVector):
        D = la._P._data
        return la._P, la._v, (lambda i: _dot(la._v, D.coroots[list(D.I).index(i)]))
    P = la._P
    I = list(P._I)
    return P, la._v, (lambda i: la._v[I.index(i)])


class _ElementaryElement(CrystalElement):
    __slots__ = ("_P", "_v")

    def __init__(self, P, v):
        self._P, self._v = P, v

    def _key(self):
        return ("elementary", self._P._kind, self._v)

    def __repr__(self):
        k = self._P._kind
        if k == "C":
            return "c"
        if k == "B":
            return str(self._v)
        return repr(self._P._la)

    def __lt__(self, other):
        return self._v < other._v

    def _e(self, i):
        P = self._P
        if P._kind == "B" and i == P._i:
            return _ElementaryElement(P, self._v + 1)
        return None

    def _f(self, i):
        P = self._P
        if P._kind == "B" and i == P._i:
            return _ElementaryElement(P, self._v - 1)
        return None

    def epsilon(self, i):
        """epsilon_i.

        EXAMPLES::

            sage: B = crystals.elementary.Elementary("A2", 1); B(2).epsilon(1), B(2).epsilon(2)
            (-2, -inf)
        """
        P = self._P
        if P._kind == "T":
            return -_INF
        if P._kind == "R":
            return _sa().Integer(-int(P._pair(i)))
        if P._kind == "C":
            return _sa().Integer(0)
        return _sa().Integer(-self._v) if i == P._i else -_INF

    def phi(self, i):
        """phi_i.

        EXAMPLES::

            sage: B = crystals.elementary.Elementary("A2", 1); B(2).phi(1), B(2).phi(2)
            (2, -inf)
        """
        P = self._P
        if P._kind == "T":
            return -_INF
        if P._kind == "R":
            return _sa().Integer(0)
        if P._kind == "C":
            return _sa().Integer(0)
        return _sa().Integer(self._v) if i == P._i else -_INF

    def _hi(self, i):
        P = self._P
        if P._kind in "TR":
            return P._pair(i)
        if P._kind == "C":
            return 0
        A = _lie._cartan(P._ct)
        return self._v * A[i][P._i]

    def _wt(self):
        P = self._P
        if P._kind in "TR":
            return P._lav
        if P._kind == "C":
            return tuple(_F(0) for x in P._zero)
        A = _lie._cartan(P._ct)
        I = list(P._ct.index_set())
        return tuple(self._v * A[j][P._i] for j in I) + (_F(0),)

    def weight(self):
        """The weight.

        EXAMPLES::

            sage: B = crystals.elementary.Elementary("A2", 1); B(2).weight()
            2*alpha[1]
        """
        P = self._P
        if P._kind in "TR":
            return P._la
        if P._kind == "C":
            return P._space.zero()
        return _Named(_lie._lincomb([(_F(self._v), "alpha[%s]" % P._i)]) or "0")


class _Named:
    def __init__(self, s):
        self._s = s

    def __repr__(self):
        return self._s


class ElementaryCrystal(Crystal):
    """The elementary crystals T_lambda, R_lambda, B_i and the component
    crystal C.

    EXAMPLES::

        sage: crystals.elementary.Component(RootSystem("A2").weight_lattice())
        The component crystal of type ['A', 2]
    """

    def __init__(self, kind, ct, la=None, i=None):
        self._kind, self._ct, self._la, self._i = kind, ct, la, i
        if la is not None:
            self._space, self._lav, self._pair = _weight_parts(la)
            self._zero = self._lav
        else:
            self._space = _lie.WeightLattice(RootSystem_(ct), False)
            self._zero = (0,)
        if kind == "T":
            self._repr = "The T crystal of type %r and weight %r" % (ct, la)
        elif kind == "R":
            self._repr = "The R crystal of weight %r and type %r" % (la, ct)
        elif kind == "C":
            self._repr = "The component crystal of type %r" % (ct,)
        else:
            self._repr = "The %s-elementary crystal of type %r" % (i, ct)
        self.module_generators = (_ElementaryElement(self, 0 if kind == "B" else None),)

    def _elements(self):
        if self._kind == "B":
            raise NotImplementedError("the elementary crystal B_i is infinite")
        return list(self.module_generators)

    def __call__(self, m=None):
        """The element (b_i(m) for B_i).

        EXAMPLES::

            sage: B = crystals.elementary.Elementary("A2", 2); B(3), B(3).f(2)
            (3, 2)
        """
        if self._kind == "B":
            return _ElementaryElement(self, int(m))
        return self.module_generators[0]

    def cardinality(self):
        """The number of elements.

        EXAMPLES::

            sage: crystals.elementary.Elementary("A2", 2).cardinality(), crystals.elementary.Component(RootSystem("A2").weight_lattice()).cardinality()
            (+Infinity, 1)
        """
        if self._kind == "B":
            return _sa().oo
        return _sa().Integer(1)


def _ct_of(ct_or_P):
    if isinstance(ct_or_P, (_lie.WeightLattice,)):
        return ct_or_P._ct
    if isinstance(ct_or_P, _lie.AmbientSpace):
        return ct_or_P._ct
    return CartanType(ct_or_P)


class _Elementary:
    """crystals.elementary: T, R, Elementary (B_i), Component."""

    def T(self, ct, la):
        """The crystal T_lambda (a single element of weight lambda).

        EXAMPLES::

            sage: P = RootSystem("C2").weight_lattice(); La = P.fundamental_weights()
            sage: T = crystals.elementary.T("C2", 2*La[1]); T, T[0].epsilon(1)
            (The T crystal of type ['C', 2] and weight 2*Lambda[1], -inf)
        """
        return ElementaryCrystal("T", _ct_of(ct), la)

    def R(self, ct, la):
        """The crystal R_lambda.

        EXAMPLES::

            sage: La = RootSystem(['B',4]).weight_lattice().fundamental_weights()
            sage: R = crystals.elementary.R(['B',4], -La[2]); R, R[0].epsilon(2)
            (The R crystal of weight -Lambda[2] and type ['B', 4], 1)
        """
        return ElementaryCrystal("R", _ct_of(ct), la)

    def Component(self, P):
        """The component crystal C (one element, epsilon = phi = 0).

        EXAMPLES::

            sage: C = crystals.elementary.Component(RootSystem("C2").weight_lattice()); C, C.list()
            (The component crystal of type ['C', 2], [c])
        """
        ct = _ct_of(P)
        if not isinstance(P, _lie.WeightLattice):
            P = _lie.WeightLattice(RootSystem_(ct), False)
        C = ElementaryCrystal("C", ct, None)
        C._space = P
        C._zero = P.zero()._v
        return C

    def Elementary(self, ct, i):
        """The i-elementary crystal B_i (elements b_i(m), m an integer).

        EXAMPLES::

            sage: B = crystals.elementary.Elementary("A2", 1); B
            The 1-elementary crystal of type ['A', 2]
            sage: S = B.subcrystal(max_depth=4, generators=[B(0)]); sorted(s for s in S)
            [-4, -3, -2, -1, 0, 1, 2, 3, 4]
            sage: B(3).weight(), B(0).phi(2)
            (3*alpha[1], -inf)
        """
        return ElementaryCrystal("B", _ct_of(ct), None, i)

    def __repr__(self):
        return "The catalog of elementary crystals"


# ------------------------------------------------------ Nakajima monomials

class _MonomialElement(CrystalElement):
    """A (modified) Nakajima monomial: the highest weight monomial times a
    product of A_{i,k}^{-1} (their multiplicities are kept)."""

    __slots__ = ("_P", "_c", "_y")

    def __init__(self, P, c):
        self._P, self._c = P, {k: v for k, v in c.items() if v}
        y = dict(P._y0)
        for (i, k), m in self._c.items():
            for key, e in P._Avec(i, k):
                y[key] = y.get(key, 0) - m * e
        self._y = {k: v for k, v in y.items() if v}

    def _key(self):
        return tuple(sorted(self._y.items()))

    def __repr__(self):
        P = self._P
        if P._vars == "A":
            if not self._c:
                return "1"
            return " ".join("A(%s,%s)^-%s" % (i, k, m) if m != 1 else "A(%s,%s)^-1" % (i, k) for (i, k), m in sorted(self._c.items()))
        if not self._y:
            return "1"
        out = []
        for (i, k), e in sorted(self._y.items()):
            out.append("Y(%s,%s)" % (i, k) + ("" if e == 1 else "^%s" % e))
        return " ".join(out)

    def _intervals(self, i):
        """[(k_start, k_end or None, prefix sum)] over the allowed range of k."""
        ks = sorted(k for (j, k) in self._y if j == i)
        out = []
        lo = 0 if self._P._inf else None
        s = 0
        start = lo
        for k in ks:
            if start is None or k > start:
                out.append((start, k - 1, s))
            s += self._y[(i, k)]
            start = k
        out.append((start, None, s))
        if self._P._inf and (not ks or ks[0] > 0):
            pass
        return out

    def phi(self, i):
        """phi_i.

        EXAMPLES::

            sage: La = RootSystem(["B",4]).weight_lattice().fundamental_weights(); M = crystals.NakajimaMonomials(["B",4], La[1]); M.list()[0].phi(1)
            1
        """
        return _sa().Integer(max(v for _, _, v in self._intervals(i)))

    def _total(self, i):
        return sum(e for (j, k), e in self._y.items() if j == i)

    def epsilon(self, i):
        """epsilon_i.

        EXAMPLES::

            sage: La = RootSystem(["B",4]).weight_lattice().fundamental_weights(); M = crystals.NakajimaMonomials(["B",4], La[1]); M.list()[1].epsilon(1)
            1
        """
        return _sa().Integer(int(self.phi(i)) - self._total(i))

    def _shift(self, i, k, d):
        c = dict(self._c)
        c[(i, k)] = c.get((i, k), 0) + d
        if c[(i, k)] < 0:
            return None
        return _MonomialElement(self._P, c)

    def _f(self, i):
        iv = self._intervals(i)
        ph = max(v for _, _, v in iv)
        if ph == 0 and not self._P._inf:
            return None
        for a, b, v in iv:
            if v == ph:
                return self._shift(i, a if a is not None else b, 1)
        return None

    def _e(self, i):
        if int(self.epsilon(i)) == 0:
            return None
        iv = self._intervals(i)
        ph = max(v for _, _, v in iv)
        k = None
        for a, b, v in iv:
            if v == ph:
                k = b
        return self._shift(i, k, -1)

    def _counts(self):
        n = {}
        for (i, k), m in self._c.items():
            n[i] = n.get(i, 0) + m
        return n

    def _wt(self):
        return self.weight()._v

    def weight(self):
        """The weight.

        EXAMPLES::

            sage: La = RootSystem(["B",4]).weight_lattice().fundamental_weights(); M = crystals.NakajimaMonomials(["B",4], La[1]); M.list()[1].weight()
            -Lambda[1] + Lambda[2]
        """
        P = self._P
        w = P._la
        al = P._space.simple_roots()
        for i, m in self._counts().items():
            w = w - m * al[i]
        return w

    def weight_in_root_lattice(self):
        """The weight minus the highest weight, in the root lattice.

        EXAMPLES::

            sage: Minf = crystals.infinity.NakajimaMonomials(['C',3,1])
            sage: Minf.highest_weight_vector().f_string([0,1,2,3,2,1,0]).weight_in_root_lattice()
            -2*alpha[0] - 2*alpha[1] - 2*alpha[2] - alpha[3]
        """
        n = self._counts()
        return _Named(_lie._lincomb([(_F(-n[i]), "alpha[%s]" % i) for i in self._P._I if n.get(i)]) or "0")


class NakajimaMonomials(Crystal):
    """The crystal of modified Nakajima monomials: B(lambda), or B(infinity)
    (lambda = None).

    EXAMPLES::

        sage: La = RootSystem(['A',2]).weight_lattice().fundamental_weights(); M = crystals.NakajimaMonomials(['A',2], La[1]); M
        Highest weight crystal of modified Nakajima monomials of Cartan type ['A', 2] and highest weight Lambda[1]
        sage: M.list()
        [Y(1,0), Y(1,1)^-1 Y(2,0), Y(2,1)^-1]
    """

    def __init__(self, ct, la, c=None, inf=False):
        self._ct = ct
        self._I = list(ct.index_set())
        self._A = _lie._cartan(ct)
        self._inf = inf
        self._vars = "Y"
        n = len(self._I)
        if c is None:
            self._cm = [[1 if a < b else 0 for b in range(n)] for a in range(n)]
        else:
            self._cm = [[int(c[a, b]) for b in range(n)] for a in range(n)]
        if inf:
            self._space = _lie.WeightLattice(RootSystem_(ct), not ct.is_finite() and getattr(ct, "_mat", None) is None)
            self._la = self._space.zero()
            self._repr = "Infinity Crystal of modified Nakajima monomials of type %r" % (ct,)
        else:
            self._space = la._P
            self._la = la
            self._repr = "Highest weight crystal of modified Nakajima monomials of Cartan type %r and highest weight %r" % (ct, la)
        y = {}
        if not inf:
            for k, i in enumerate(self._I):
                if la._v[k]:
                    y[(i, 0)] = int(la._v[k])
        self._y0 = y
        self.module_generators = (_MonomialElement(self, {}),)

    def _Avec(self, i, k):
        """The exponents of A_{i,k}."""
        a = self._I.index(i)
        out = [((i, k), 1), ((i, k + 1), 1)]
        for b, j in enumerate(self._I):
            if j != i and self._A[j][i]:
                out.append(((j, k + self._cm[b][a]), int(self._A[j][i])))
        return out

    def _realize(self, v):
        return _lie.AffineWeight(self._space, v)

    def _Lambda(self):
        return self._space.fundamental_weights()

    def c(self):
        """The matrix (c_ij) used in A_{i,k}.

        EXAMPLES::

            sage: La = RootSystem(['C',3]).weight_lattice().fundamental_weights()
            sage: crystals.NakajimaMonomials(['C',3], 2*La[1]).c()
            [0 1 1]
            [0 0 1]
            [0 0 0]
        """
        return _sa().matrix(_sa().ZZ, self._cm)

    def set_variables(self, v):
        """Print monomials in the Y (default) or A variables.

        EXAMPLES::

            sage: Minf = crystals.infinity.NakajimaMonomials(['A',2]); m = Minf.highest_weight_vector().f(1)
            sage: Minf.set_variables('A'); m
            A(1,0)^-1
            sage: Minf.set_variables('Y'); m
            Y(1,0)^-1 Y(1,1)^-1 Y(2,0)
        """
        self._vars = v

    def _elements(self):
        if self._inf or not self._ct.is_finite():
            raise NotImplementedError("the crystal is infinite")
        return Crystal._elements(self)


def _nakajima(ct, la=None, c=None):
    """crystals.NakajimaMonomials(cartan_type, la): B(la) by monomials.

    EXAMPLES::

        sage: La = RootSystem(['B',4]).weight_lattice().fundamental_weights()
        sage: M = crystals.NakajimaMonomials(['B',4], La[1]+La[2]); M.list()[:3], M.cardinality()
        ([Y(1,0) Y(2,0), Y(1,1)^-1 Y(2,0)^2, Y(2,0) Y(2,1)^-1 Y(3,0)], 231)
        sage: c = Matrix([[0,0,1],[1,0,0],[0,1,0]]); La = RootSystem(['C',3]).weight_lattice().fundamental_weights()
        sage: M = crystals.NakajimaMonomials(2*La[1], c=c); M.list()[:3]
        [Y(1,0)^2, Y(1,0) Y(1,1)^-1 Y(2,1), Y(1,1)^-2 Y(2,1)^2]
    """
    if la is None and isinstance(ct, _lie.AffineWeight):
        ct, la = ct._P._ct, ct
    return NakajimaMonomials(CartanType(ct), la, c)


# ------------------------------------------------ B(infinity): tableaux (type A)

class _InfTableauElement(CrystalElement):
    """A marginally large tableau (an element of B(infinity) of type A_n)."""

    __slots__ = ("_P", "_rows")

    def __init__(self, P, rows):
        self._P, self._rows = P, tuple(tuple(r) for r in rows)

    def _key(self):
        return self._rows

    def __repr__(self):
        return repr([list(r) for r in self._rows])

    def pp(self):
        """Print the tableau.

        EXAMPLES::

            sage: B = crystals.infinity.Tableaux(['A',2]); B.highest_weight_vector().f(2).pp()
              1  1  1
              2  3
        """
        print("\n".join("".join("%3s" % x for x in r) for r in self._rows if r))

    def to_tableau(self):
        """The tableau.

        EXAMPLES::

            sage: B = crystals.infinity.Tableaux(['A',2]); B.highest_weight_vector().f(2).to_tableau()
            [[1, 1, 1], [2, 3]]
        """
        return Tableau([list(r) for r in self._rows if r])

    def _word(self):
        L = self._P._letters
        rows = [r for r in self._rows]
        w = []
        for j in range(len(rows[0]) if rows else 0):
            col = [rows[r][j] for r in range(len(rows)) if j < len(rows[r])]
            w += [L(x) for x in reversed(col)]
        return w

    def _from_word(self, w):
        shape = [len(r) for r in self._rows]
        cols = _col_lengths(shape)
        rows = [[] for _ in shape]
        k = 0
        for c in cols:
            col = [w[k + t]._v for t in range(c)]
            k += c
            for r, x in enumerate(reversed(col)):
                rows[r].append(x)
        return self._P._normalize(rows)

    def _op(self, i, lower):
        w = self._word()
        f, e, _, _ = _signature(w, i)
        j = f if lower else e
        if j is None:
            if lower:
                # act on a new trivial column (1, ..., i) added first
                rows = [[r + 1] + list(row) if r < i else list(row) for r, row in enumerate(self._rows)]
                el = _InfTableauElement(self._P, rows)
                return el._op(i, True)
            return None
        w[j] = w[j].f(i) if lower else w[j].e(i)
        return self._from_word(w)

    def _f(self, i):
        return self._op(i, True)

    def _e(self, i):
        if int(self.epsilon(i)) == 0:
            return None
        return self._op(i, False)

    def epsilon(self, i):
        """epsilon_i.

        EXAMPLES::

            sage: B = crystals.infinity.Tableaux(['A',2]); b = B.highest_weight_vector().f(1); b.epsilon(1), b.phi(1)
            (1, -1)
        """
        return _sa().Integer(_signature(self._word(), i)[2])

    def phi(self, i):
        """phi_i = epsilon_i + <wt, h_i>.

        EXAMPLES::

            sage: B = crystals.infinity.Tableaux(['A',2]); b = B.highest_weight_vector(); b.phi(1), b.f(1).phi(1)
            (0, -1)
        """
        w = self._wt()
        return self.epsilon(i) + _sa().Integer(int(w[i - 1] - w[i]))

    def _wt(self):
        d = self._P._ct._n + 1
        v = [_F(0)] * d
        for r, row in enumerate(self._rows):
            v[r] -= len(row)
            for x in row:
                v[x - 1] += 1
        return tuple(v)


class InfinityCrystalOfTableaux(Crystal):
    """B(infinity) of type A_n by marginally large tableaux.

    EXAMPLES::

        sage: B = crystals.infinity.Tableaux(['A',2]); B
        The infinity crystal of tableaux of type ['A', 2]
        sage: B.highest_weight_vector().f_string([1, 2])
        [[1, 1, 3], [2]]
    """

    def __init__(self, ct):
        if ct._letter != "A" or not ct.is_finite():
            raise NotImplementedError("infinity crystals of tableaux of type %r are not available in sagebrush yet" % (ct,))
        self._ct = ct
        self._space = RootSystem_(ct).ambient_space()
        self._letters = CrystalOfLetters(ct)
        self._repr = "The infinity crystal of tableaux of type %r" % (ct,)
        n = ct._n
        self.module_generators = (self._normalize([[] for _ in range(n)]),)

    def _normalize(self, rows):
        """Add or remove trivial columns (1, ..., r) so that row r has exactly
        one more r than row r+1 has boxes."""
        n = self._ct._n
        rows = [list(r) for r in rows] + [[] for _ in range(n - len(rows))]
        for r in range(n - 1, -1, -1):
            need = (len(rows[r + 1]) if r + 1 < n else 0) + 1
            have = sum(1 for x in rows[r] if x == r + 1)
            while have < need:
                for s in range(r + 1):
                    rows[s].insert(0, s + 1)
                have += 1
            while have > need:
                for s in range(r + 1):
                    rows[s].pop(0)
                have -= 1
        return _InfTableauElement(self, rows)

    def _elements(self):
        raise NotImplementedError("the crystal is infinite")

    def cardinality(self):
        """Infinity.

        EXAMPLES::

            sage: B = crystals.infinity.Tableaux(['A',2]); B.cardinality()
            +Infinity
        """
        return _sa().oo

    def highest_weight_vector(self):
        """The highest weight element.

        EXAMPLES::

            sage: B = crystals.infinity.Tableaux(['A',2]); B.highest_weight_vector()
            [[1, 1], [2]]
        """
        return self.module_generators[0]


def crystal_morphism(source, on_gens):
    """The crystal morphism sending the highest weight elements of source as
    given (a dict), commuting with the f_i.

    EXAMPLES::

        sage: Brho = crystals.Tableaux(['A',2], shape=[2,1]); brho = Brho.highest_weight_vector()
        sage: B = crystals.infinity.Tableaux(['A',2]); T = crystals.elementary.T(['A',2], brho.weight())
        sage: TB = crystals.TensorProduct(T, B); Psi = Brho.crystal_morphism({brho: TB(T[0], B.highest_weight_vector())})
        sage: [Psi(x) for x in Brho][:3]
        [[(2, 1, 0), [[1, 1], [2]]], [(2, 1, 0), [[1, 1, 2], [2]]], [(2, 1, 0), [[1, 1, 3], [2]]]]
    """
    def Psi(x):
        hw, path = x.to_highest_weight()
        y = on_gens[hw]
        for i in reversed(path):
            if y is None:
                return None
            y = y.f(i)
        return y
    return Psi


class _Infinity:
    """crystals.infinity: Tableaux (type A), NakajimaMonomials."""

    def Tableaux(self, ct):
        """B(infinity) by marginally large tableaux (type A).

        EXAMPLES::

            sage: B = crystals.infinity.Tableaux(['A',2]); b = B.highest_weight_vector(); b
            [[1, 1], [2]]
            sage: b.f_string([1,2,2,1,2,1,2,2,2,2,2]).pp()
              1  1  1  1  1  1  1  1  1  2  2  3
              2  3  3  3  3  3  3  3
        """
        return InfinityCrystalOfTableaux(CartanType(ct))

    def NakajimaMonomials(self, ct, c=None):
        """B(infinity) by modified Nakajima monomials.

        EXAMPLES::

            sage: Minf = crystals.infinity.NakajimaMonomials(['C',3,1]); minf = Minf.highest_weight_vector()
            sage: m = minf.f_string([0,1,2,3,2,1,0]); m, m.weight()
            (Y(0,0)^-1 Y(0,4)^-1 Y(1,0) Y(1,3), -2*Lambda[0] + 2*Lambda[1] - 2*delta)
        """
        M = NakajimaMonomials(CartanType(ct), None, c, inf=True)
        M.highest_weight_vector = lambda: M.module_generators[0]
        return M

    def __repr__(self):
        return "The catalog of infinity crystals"


# ------------------------------------------------------------- LS paths

class _LSPath(CrystalElement):
    """A Lakshmibai-Seshadri (Littelmann) path: a tuple of straight segments
    (their displacement vectors, in the weight space)."""

    __slots__ = ("_P", "_s")

    def __init__(self, P, segs):
        self._P, self._s = P, _merge(segs)

    def _key(self):
        return self._s

    def __repr__(self):
        W = self._P._space
        return "(" + ", ".join(repr(_lie.AffineWeight(W, v)) for v in self._s) + ("," if len(self._s) == 1 else "") + ")"

    def value(self):
        """The segments (as weights).

        EXAMPLES::

            sage: C = crystals.LSPaths(['A',2], [1,0]); C.list()[1].value()
            (-Lambda[1] + Lambda[2],)
        """
        W = self._P._space
        return tuple(_lie.AffineWeight(W, v) for v in self._s)

    def _h(self, i):
        k = self._P._ipos[i]
        hs = [_F(0)]
        for v in self._s:
            hs.append(hs[-1] + v[k])
        return hs

    def epsilon(self, i):
        """epsilon_i: minus the minimum of <pi(t), alpha_i^vee>.

        EXAMPLES::

            sage: C = crystals.LSPaths(['A',2], [2,0]); C.list()[1].epsilon(1), C.list()[1].phi(1)
            (1, 1)
        """
        return _sa().Integer(int(-min(self._h(i))))

    def phi(self, i):
        """phi_i: the endpoint minus the minimum of <pi(t), alpha_i^vee>.

        EXAMPLES::

            sage: C = crystals.LSPaths(['A',2], [1,0]); C.list()[0].phi(1), C.list()[1].phi(2)
            (1, 1)
        """
        hs = self._h(i)
        return _sa().Integer(int(hs[-1] - min(hs)))

    def _reflect(self, i, v):
        k = self._P._ipos[i]
        a = self._P._alpha[i]
        c = v[k]
        return tuple(x - c * y for x, y in zip(v, a))

    def _f(self, i):
        hs = self._h(i)
        m = min(hs)
        if hs[-1] - m < 1:
            return None
        t0 = max(k for k, h in enumerate(hs) if h == m)
        segs = list(self._s)
        # the first crossing of m + 1 after t0
        for k in range(t0 + 1, len(hs)):
            if hs[k] >= m + 1:
                break
        p = (m + 1 - hs[k - 1]) / (hs[k] - hs[k - 1])
        v = segs[k - 1]
        first, rest = _smul(p, v), _smul(1 - p, v)
        new = segs[:t0] + [self._reflect(i, w) for w in segs[t0:k - 1]] + [self._reflect(i, first)]
        if p != 1:
            new.append(rest)
        new += segs[k:]
        return _LSPath(self._P, new)

    def _e(self, i):
        hs = self._h(i)
        m = min(hs)
        if m > -1:
            return None
        t1 = min(k for k, h in enumerate(hs) if h == m)
        segs = list(self._s)
        j = max(k for k in range(t1) if hs[k] >= m + 1)
        # crossing of m + 1 in segment j (between breakpoints j and j + 1)
        p = (hs[j] - (m + 1)) / (hs[j] - hs[j + 1])
        v = segs[j]
        first, rest = _smul(p, v), _smul(1 - p, v)
        new = segs[:j]
        if p != 0:
            new.append(first)
        new += [self._reflect(i, rest)] + [self._reflect(i, w) for w in segs[j + 1:t1]] + segs[t1:]
        return _LSPath(self._P, new)

    def _wt(self):
        d = len(self._s[0])
        w = tuple([_F(0)] * d)
        for v in self._s:
            w = _addv(w, v)
        return w

    def weight(self):
        """The endpoint.

        EXAMPLES::

            sage: C = crystals.LSPaths(['A',2], [2,0]); C.list()[1].weight()
            Lambda[2]
        """
        return _lie.AffineWeight(self._P._space, self._wt())


def _merge(segs):
    out = []
    for v in segs:
        v = tuple(_F(x) for x in v)
        if all(x == 0 for x in v):
            continue
        if out:
            u = out[-1]
            k = next(t for t, x in enumerate(u) if x != 0)
            c = v[k] / u[k]
            if c > 0 and all(b == c * a for a, b in zip(u, v)):
                out[-1] = _addv(u, v)
                continue
        out.append(v)
    return tuple(out)


class LSPaths(Crystal):
    """The crystal of Lakshmibai-Seshadri paths of a weight.

    EXAMPLES::

        sage: C = crystals.LSPaths(['A',2], [1,0]); C, C.list()
        (The crystal of LS paths of type ['A', 2] and weight Lambda[1], [(Lambda[1],), (-Lambda[1] + Lambda[2],), (-Lambda[2],)])
    """

    def __init__(self, la):
        W = la._P
        self._space = W
        self._ct = W._ct
        self._la = la
        I = list(W._I)
        self._ipos = {i: k for k, i in enumerate(I)}
        al = W.simple_roots()
        self._alpha = {i: al[i]._v for i in I}
        self._repr = "The crystal of LS paths of type %r and weight %r" % (self._ct, la)
        self.module_generators = (_LSPath(self, [la._v]),)

    def _realize(self, v):
        return _lie.AffineWeight(self._space, v)

    def _Lambda(self):
        return self._space.fundamental_weights()

    def _elements(self):
        if not self._ct.is_finite():
            raise NotImplementedError("the crystal is infinite")
        return Crystal._elements(self)


def _lspaths(starting_weight, weight=None):
    """crystals.LSPaths(weight) or crystals.LSPaths(cartan_type, [coefficients]).

    EXAMPLES::

        sage: C = crystals.LSPaths(['A',2], [1,1]); C
        The crystal of LS paths of type ['A', 2] and weight Lambda[1] + Lambda[2]
        sage: C.list()[:3]
        [(Lambda[1] + Lambda[2],), (-Lambda[1] + 2*Lambda[2],), (1/2*Lambda[1] - Lambda[2], -1/2*Lambda[1] + Lambda[2])]
        sage: R = RootSystem(['A',2,1]); La = R.weight_space(extended=True).basis()
        sage: LS = crystals.LSPaths(La[1] - La[0]); sorted(LS.subcrystal(max_depth=2, direction='both'), key=str)
        [(-Lambda[0] + Lambda[1],), (-Lambda[1] + Lambda[2] + delta,), (-Lambda[1] + Lambda[2],), (Lambda[0] - Lambda[2] + delta,), (Lambda[0] - Lambda[2],)]
    """
    if weight is not None:
        ct = CartanType(starting_weight)
        W = _lie.WeightLattice(RootSystem_(ct), False)
        W._space_name = True
        La = W.fundamental_weights()
        la = W.zero()
        for i, c in zip(ct.index_set(), weight):
            la = la + int(c) * La[i]
        return LSPaths(la)
    return LSPaths(starting_weight)


class _Crystals:
    """The catalog of crystals (crystals.Letters, crystals.Tableaux, ...)."""

    def __init__(self):
        self.Letters = Letters
        self.Tableaux = Tableaux
        self.Spins = Spins
        self.SpinsPlus = SpinsPlus
        self.SpinsMinus = SpinsMinus
        self.TensorProduct = TensorProduct
        self.HighestWeight = HighestWeight
        self.FastRankTwo = FastRankTwo
        self.KirillovReshetikhin = KirillovReshetikhin
        self.elementary = _Elementary()
        self.NakajimaMonomials = _nakajima
        self.infinity = _Infinity()
        self.LSPaths = _lspaths

    def __repr__(self):
        return "The catalog of crystals"


crystals = _Crystals()


_KRElement.__module__ = "sage.combinat.crystals.kirillov_reshetikhin"
_KRElement.__qualname__ = "KR_type_A_with_category.element_class"
_TableauElement.__module__ = "sage.combinat.crystals.tensor_product"
_TableauElement.__qualname__ = "CrystalOfTableaux_with_category.element_class"

files._sage_expr.py:
"""Sage's symbolic ring: x = var('x'); diff(sin(x^2)/x, x).

An Expression is a handle on an expression of the Rust symbolic engine
(engine/sym): it holds the engine's canonical serialization, so equal
expressions have equal strings, and every operation is one stateless call
into the engine (simplification, printing, calculus, solving all happen
there).  This module only translates between Python values and the engine
and gives the results Sage's methods and printing.
"""

import math as _m
import re as _re
from fractions import Fraction as _Fraction
import sys as _sys
import _display_budget
from _display_budget import _charge

try:  # the CPython package
    from sagebrush._native import sym_call as _raw
except ImportError:  # pyjs: the engine is linked into the runtime
    import _sbengine
    _raw = _sbengine.sym

_SEP = "\x1f"
_ERRORS = {"ZeroDivisionError": ZeroDivisionError, "ValueError": ValueError,
           "NotImplementedError": NotImplementedError}



def _is_symbolic_function(v):
    """Whether v is a callable expression f(x) = ... (_sage_lang's
    SymbolicFunction, whose type shows as Sage's Expression)."""
    import _sage_lang
    return isinstance(v, _sage_lang.SymbolicFunction)

def _call(op, *args):
    r = _raw(_SEP.join((op,) + args)).split(_SEP)
    if r[0] == "ok":
        return r[1:]
    raise _ERRORS.get(r[1], RuntimeError)(r[2] if len(r) > 2 else "symbolic engine error")


def _one(op, *args):
    return Expression(_call(op, *args)[0])


# ------------------------------------------------------------------ conversion

def _is_poly(v):
    return hasattr(v, "_c") and hasattr(v, "variable_name") and hasattr(v, "_ring")


def _sym_s(name):
    return "s%d:%s" % (len(name.encode()), name)


def _float_s(v):
    return _call("float", repr(float(v)))[0]


# The largest integer an expression may hold (the engine's MAX_INT_BITS):
# expressions cross into the engine as decimal text, so a larger one is
# refused before it is formatted, as CPython refuses int-to-str past its
# digit limit.
_MAX_INT_BITS = 1 << 21


def _rat_s(p, q=1):
    """The engine serialization of the rational p/q (q > 0, exact ints)."""
    bits = max(p.bit_length(), q.bit_length())
    if bits > _MAX_INT_BITS:
        raise NotImplementedError(
            "an integer of %d bits in a symbolic expression: sagebrush's "
            "symbolic ring holds integers of at most %d bits" % (bits, _MAX_INT_BITS))
    return "n%d/%d;" % (p, q)


def _to_s(v):
    """The engine serialization of a Python value, or None."""
    if isinstance(v, Expression):
        return v._s
    if isinstance(v, int):
        return _rat_s(int(v))
    if isinstance(v, _Fraction):
        # exact ints first: formatting an int subclass must not round it
        return _rat_s(int(v.numerator), int(v.denominator))
    if isinstance(v, float):
        if _rr_args((v,)) == 2:
            # (the engine's real numbers are doubles)
            raise NotImplementedError("%s, an element of RR past the double range, has no symbolic form in sagebrush yet" % (v,))
        return _float_s(v)
    if isinstance(v, complex):
        if v.imag == 0:
            return _float_s(v.real)
        return _call("complex", repr(v.real), repr(v.imag))[0]
    if _is_poly(v):
        t, r = Expression(_sym_s(v.variable_name())), Expression("n0/1;")
        for i, c in enumerate(v._c):
            if c != 0:
                r = r + _expr(c) * t ** i
        return r._s
    sr = getattr(v, "_symbolic_", None)
    if sr is not None:
        return _to_s(sr())
    if hasattr(v, "numerator") and hasattr(v, "denominator"):
        try:
            p, q = v.numerator, v.denominator
            p, q = (p() if callable(p) else p), (q() if callable(q) else q)
            return _rat_s(int(p), int(q)) if int(q) > 0 else None
        except (TypeError, ValueError):
            return None
    return None


def _expr(v):
    """v as an Expression (SR(v)); TypeError if it has no symbolic form."""
    if isinstance(v, Expression):
        return v
    if isinstance(v, str):
        return Expression(_call("parse", v)[0])
    if _is_symbolic_function(v) and not v._vec:
        return v._expr
    s = _to_s(v)
    if s is None:
        raise TypeError("cannot convert %r to a symbolic expression" % (v,))
    return Expression(s)


SR = _expr


def _py_number(s):
    """The Python value of an exact rational or a float expression, or None."""
    r = _call("number", s)
    if r[0] == "q":
        p, q = r[1].split("/")
        import sage_all as sa
        return sa._intdiv(int(p), int(q)) if q != "1" else sa.Integer(int(p))
    if r[0] == "f" and float(r[2]) == 0:
        from _sage_lang import RealNumber
        return RealNumber(float(r[1]))
    return None


_INFINITIES = {"+Infinity": 1, "-Infinity": -1, "Infinity": 0}


def _infinite_relation(kind, a, b):
    """bool(a <kind> b) when a or b is an infinity (a - b is then an
    infinity or NaN, which decides nothing); None otherwise.  A signed
    infinity is ordered against a constant only when the constant has a
    certified real sign; anything else undecided is False, as in Sage."""
    ra, rb = repr(a), repr(b)
    ia, ib = _INFINITIES.get(ra), _INFINITIES.get(rb)
    if ia is None and ib is None:
        return None
    if ia is not None and ib is not None:
        if kind in ("==", "!="):
            return (ra == rb) == (kind == "==")
        if ia == 0 or ib == 0:
            return False
        return {"<": ia < ib, "<=": ia <= ib, ">": ia > ib, ">=": ia >= ib}[kind]
    c = b if ia is not None else a
    if c.variables() or repr(c) == "NaN":
        return None if kind in ("==", "!=") else False
    if kind in ("==", "!="):
        return kind == "!="
    s = ia if ia is not None else ib
    if s == 0 or _call("const_sign", c._s)[0] == "":
        return False
    # a finite real constant lies strictly between -oo and +oo
    sa, sb = (s, 0) if ia is not None else (0, s)
    return {"<": sa < sb, "<=": sa < sb, ">": sa > sb, ">=": sa > sb}[kind]


def _numerically_equal(a, b):
    """Heuristic equality of two constants that the engine could neither
    simplify to equal nor separate: their difference, evaluated at 400 bits,
    is below 2^-300 relative to them.  (A double, which underflows or
    cancels, is never used.)"""
    import _sage_real
    try:
        d = abs(_sage_real.N(a - b, 400))
        m = max(abs(_sage_real.N(a, 400)), abs(_sage_real.N(b, 400)), 1)
        return bool(d <= m * _sage_real.N(Expression("2") ** -300, 400))
    except Exception:
        return False


def _relop(sym):
    return {"Eq": "==", "Ne": "!=", "Lt": "<", "Le": "<=", "Gt": ">", "Ge": ">="}[sym]


# ------------------------------------------------------------------ Expression

class Expression:
    """An element of Sage's symbolic ring.

    EXAMPLES::

        sage: f = x^2 + 2*x + 1; f
        x^2 + 2*x + 1
        sage: f.factor(), f.diff(x), f.integrate(x), f(x=3)
        ((x + 1)^2, 2*x + 2, 1/3*x^3 + x^2 + x, 16)
    """

    __slots__ = ("_s", "_repr", "_fast", "_h", "__weakref__")

    def __init__(self, s):
        if _SPECIAL_RE.search(s) and _FLOAT_RE.search(s):
            s = _complete_special(s)
        self._s, self._repr, self._fast, self._h = s, None, None, None

    def __reduce__(self):
        return (Expression, (self._s,))

    def parent(self):
        """The symbolic ring SR.

        EXAMPLES::

            sage: x.parent()
            Symbolic Ring
        """
        return SR_parent

    # --- arithmetic
    def _bin(self, op, other, rev=False):
        o = _to_s(other)
        if o is None:
            return NotImplemented
        r = _one(op, o, self._s) if rev else _one(op, self._s, o)
        if r._s == "c?" and op in _SIGN_ERRORS and ("c+" in (o, self._s) or "c-" in (o, self._s)):
            # oo*0, oo - oo: Sage's infinity raises (SignError), where the
            # engine's arithmetic gives NaN
            raise SignError(_SIGN_ERRORS[op])
        return r

    def __add__(self, o): return self._bin("add", o)
    def __radd__(self, o): return self._bin("add", o, True)
    def __sub__(self, o): return self._bin("sub", o)
    def __rsub__(self, o): return self._bin("sub", o, True)
    def __mul__(self, o): return self._bin("mul", o)
    def __rmul__(self, o): return self._bin("mul", o, True)
    def __truediv__(self, o): return self._bin("div", o)
    def __rtruediv__(self, o): return self._bin("div", o, True)
    def __pow__(self, o, mod=None):
        if mod is not None:
            # (the modulus was ignored: pow(SR(2), 3/2, 5) was 2*sqrt(2)), as Sage
            raise TypeError("the 3-argument version of pow() is not supported")
        return self._bin("pow", o)
    def __rpow__(self, o): return self._bin("pow", o, True)
    def __xor__(self, o): raise RuntimeError("Use ** for exponentiation, not '^', which means xor\nin Python, and has the wrong precedence.")
    __rxor__ = __xor__
    def __neg__(self): return _one("neg", self._s)
    def __pos__(self): return self
    def __abs__(self):
        r = _one("fun", "abs", self._s)
        if _ASSUMPTIONS and r._op()[0] == "fun:abs":
            sg = _sign_of(self)
            if sg is not None:
                return self if sg >= 0 else -self
        return r

    # --- relations: x == 2 is an equation; bool() decides it
    def _rel(self, op, other):
        o = _to_s(other)
        if o is None:
            return NotImplemented
        return _one("rel", op, self._s, o)

    def __eq__(self, o): return self._rel("==", o)
    def __ne__(self, o): return self._rel("!=", o)
    def __lt__(self, o): return self._rel("<", o)
    def __le__(self, o): return self._rel("<=", o)
    def __gt__(self, o): return self._rel(">", o)
    def __ge__(self, o): return self._rel(">=", o)

    def __hash__(self):
        # an exact number hashes as that number (SR(1) == 1 with different
        # hashes broke dictionaries and sets: the systematic review's API-F2),
        # and a polynomial with rational coefficients as the polynomial does
        # (t == SR(t): R2-API-F1); cached
        h = self._h
        if h is not None:
            return h
        s = self._s
        h = None
        if s.startswith("n") and s.endswith(";") and "/" in s:
            try:
                num, den = s[1:-1].split("/")
                h = hash(_Fraction(int(num), int(den)))
            except ValueError:
                pass
        if h is None and not self.is_relational():
            terms = _sr_poly_terms(self, sorted(self._names()))
            if terms is not None:
                from _sage_poly import poly_hash
                h = poly_hash(terms)
        if h is None:
            h = hash(s)
        self._h = h
        return h

    def __bool__(self):
        op = self._op()
        if op[0].startswith("rel:"):
            kind = _relop(op[0][4:])
            a, b = Expression(op[1]), Expression(op[2])
            inf = _infinite_relation(kind, a, b)
            if inf is not None:
                return inf
            if kind in ("==", "!="):
                z = _call("is_zero", (a - b)._s)[0] == "1"
                if not z and kind == "==" and not (a - b).variables() and _call("const_sign", (a - b)._s)[0] == "":
                    # constants of undecided sign: equal if they agree to
                    # far more than double precision (never from an
                    # underflowed or cancelled double)
                    z = _numerically_equal(a, b)
                if not z and _ASSUMPTIONS and (a - b).variables():
                    # the rewritten difference tested directly: bool() of
                    # (rewrite == 0) came back here and rewrote again,
                    # without end when the rewrite changed nothing (any
                    # comparison under assume(x > 0): the review's SOLVE2-F6)
                    z = _call("is_zero", _assume_rewrite(a - b).expand()._s)[0] == "1"
                return z if kind == "==" else not z
            if (a - b).variables():
                if _ASSUMPTIONS:
                    for r in _ASSUMPTIONS:
                        if isinstance(r, Expression) and str(r) == str(self):
                            return True
                return False
            # constants: only a certified sign of a - b decides (exact for
            # rationals); undecided is False, as in Sage
            sg = _call("const_sign", (a - b)._s)[0]
            if sg == "":
                return False
            sg = int(sg)
            return {"<": sg < 0, "<=": sg <= 0, ">": sg > 0, ">=": sg >= 0}[kind]
        return _call("is_zero", self._s)[0] != "1"

    def lhs(self):
        """The left-hand side of an equation (also left()).

        EXAMPLES::

            sage: (x^2 == 4).lhs(), (x < 1).left_hand_side()
            (x^2, x)
        """
        op = self._op()
        if not op[0].startswith("rel:"):
            raise AttributeError("lhs: not a relation")
        return Expression(op[1])

    def rhs(self):
        """The right-hand side of an equation (also right()).

        EXAMPLES::

            sage: (x^2 == 4).rhs(), (x < 1).right()
            (4, 1)
        """
        op = self._op()
        if not op[0].startswith("rel:"):
            raise AttributeError("rhs: not a relation")
        return Expression(op[2])

    left = left_hand_side = lhs
    right = right_hand_side = rhs

    # --- printing
    def __repr__(self):
        if self._repr is None:
            self._repr = _call("str", self._s)[0]
        return self._repr

    __str__ = __repr__

    def _latex_(self):
        t = _call("latex", self._s)[0]
        for n, l in _LATEX_NAMES.items():
            # (the symbol alone, as written or as rendered: _y is _{y})
            if n not in _LATEX_SYM:
                _LATEX_SYM[n] = _call("latex", _sym_s(n))[0]
            if t == n or t == _LATEX_SYM[n]:
                return l
            t = t.replace("\\mathit{%s}" % n, l)
        return t

    def __format__(self, spec):
        return format(str(self), spec)

    # --- structure
    def _op(self):
        return _call("operator", self._s)

    def variables(self):
        """The variables, sorted.

        EXAMPLES::

            sage: var('y z')
            (y, z)
            sage: (x + z*y).variables()
            (x, y, z)
        """
        return tuple(Expression(_sym_s(n)) for n in _call("variables", self._s) if n)

    arguments = args = variables

    def _names(self):
        return [n for n in _call("variables", self._s) if n]

    def operator(self):
        """The top-level operation.

        EXAMPLES::

            sage: (x^2).operator(), (x + 1).operator()  # sagebrush only
            (<function pow at 0x...>, <function add at 0x...>)
        """
        import operator as o
        tag = self._op()[0]
        if tag == "add":
            return o.add
        if tag == "mul":
            return o.mul
        if tag == "pow":
            return o.pow
        if tag.startswith("rel:"):
            return {"Eq": o.eq, "Ne": o.ne, "Lt": o.lt, "Le": o.le, "Gt": o.gt, "Ge": o.ge}[tag[4:]]
        if tag.startswith("fun:"):
            return _functions.get(tag[4:]) or function(tag[4:])
        return None

    def operands(self):
        """The operands of the top-level operation.

        EXAMPLES::

            sage: (x^2 + 3*x).operands()
            [x^2, 3*x]
        """
        return [Expression(s) for s in self._op()[1:]]

    def number_of_operands(self):
        """The number of operands (also nops()).

        EXAMPLES::

            sage: (x + 1).number_of_operands(), (x^2).nops()
            (2, 2)
        """
        return len(self._op()) - 1

    nops = number_of_operands

    def is_symbol(self):
        """Whether the expression is a single variable.

        EXAMPLES::

            sage: x.is_symbol(), (x + 1).is_symbol()
            (True, False)
        """
        return self._s.startswith("s")

    def is_numeric(self):
        """Whether the expression is a number.

        EXAMPLES::

            sage: SR(2/3).is_numeric(), pi.is_numeric()
            (True, False)
        """
        return self._s[0] in "nzfg"

    def is_constant(self):
        """Whether the expression has no variables.

        EXAMPLES::

            sage: pi.is_constant(), x.is_constant()
            (True, False)
        """
        return not self._names()

    def is_relational(self):
        """Whether the expression is an equation or inequality.

        EXAMPLES::

            sage: (x == 1).is_relational(), (x + 1).is_relational()
            (True, False)
        """
        return self._s.startswith("R")

    def is_zero(self):
        """Whether the expression is zero (after simplification).

        EXAMPLES::

            sage: (x - x).is_zero(), (sin(x)^2 + cos(x)^2 - 1).is_zero()
            (True, True)
        """
        return _call("is_zero", self._s)[0] == "1"

    def is_trivial_zero(self):
        """Whether the expression is literally 0.

        EXAMPLES::

            sage: SR(0).is_trivial_zero(), (x - x).is_trivial_zero()
            (True, True)
        """
        return self._s == "n0/1;"

    def is_integer(self):
        """Whether the expression is an integer.

        EXAMPLES::

            sage: SR(3).is_integer(), (x + 1).is_integer()
            (True, False)
        """
        v = _py_number(self._s)
        return isinstance(v, int) and not isinstance(v, float)

    def is_rational_expression(self):
        """Whether the expression is a rational function: a quotient of
        polynomials in its variables.

        EXAMPLES::

            sage: (1/(x + 1)).is_rational_expression(), sin(x).is_rational_expression()
            (True, False)
        """
        n, d = self.numerator_denominator()
        vs = self.variables()
        if not vs:
            return self.is_numeric()
        return all(n.is_polynomial(v) and d.is_polynomial(v) for v in vs)

    def is_polynomial(self, var):
        """Whether the expression is a polynomial in x.

        EXAMPLES::

            sage: (x^2 + 1).is_polynomial(x), (1/x).is_polynomial(x)
            (True, False)
        """
        try:
            self.coefficients(var)
            return True
        except ValueError:
            return False

    # --- substitution and evaluation
    def subs(self, *args, **kw):
        """subs(x=2), subs({x: 2}), subs(x == 2), subs([x == 1, y == 2]).

        EXAMPLES::

            sage: f = x^2 + 1
            sage: f.subs(x=2), f.subs({x: x + 1}), f.subs(x == 3)
            (5, (x + 1)^2 + 1, 10)
        """
        pairs = []

        def add(a):
            if isinstance(a, dict):
                for k, v in a.items():
                    pairs.extend((_expr(k)._s, _expr(v)._s))
            elif isinstance(a, (list, tuple)):
                for r in a:
                    add(r)
            elif isinstance(a, Expression) and a.is_relational():
                pairs.extend((a.lhs()._s, a.rhs()._s))
            else:
                raise TypeError("subs: expected a relation or a dictionary, got %r" % (a,))
        for a in args:
            add(a)
        for k, v in kw.items():
            pairs.extend((_sym_s(k), _expr(v)._s))
        if not pairs:
            return self
        return _one("subs", self._s, *pairs)

    substitute = subs

    def __call__(self, *args, **kw):
        """f(2), f(x=2): substitute (positionally, in the order of variables()).

        EXAMPLES::

            sage: var('y')
            y
            sage: f = x^2 + y
            sage: f(2, 3), f(x=1), f(y=x)  # sagebrush only
            (7, y + 1, x^2 + x)
        """
        names = self._names()
        if len(args) > len(names):
            raise ValueError("the number of arguments must be less than or equal to %d" % len(names))
        d = {Expression(_sym_s(n)): a for n, a in zip(names, args)}
        return self.subs(d, **kw)

    def function(self, *args):
        """The callable expression args |--> self (what f(x) = ... makes).

        EXAMPLES::

            sage: (x^2 + 1).function(x)
            x |--> x^2 + 1
            sage: (x^2 + 1).function(x)(3)
            10
        """
        from _sage_lang import SymbolicFunction
        return SymbolicFunction(self, args)

    def n(self, prec=None, digits=None):
        """The numerical value: an element of RR, or of CC if it is complex
        (or of RealField(prec), ComplexField(prec)).

        EXAMPLES::

            sage: pi.n(), sqrt(2).n(), (1 + I).n(), exp(1).N()  # sagebrush only
            (3.14159265358979, 1.41421356237310, 1.00000000000000 + 1.00000000000000*I, 2.71828182845905)
        """
        if self.is_relational():
            return _one("rel", _relop(self._op()[0][4:]), _expr(self.lhs().n())._s, _expr(self.rhs().n())._s)
        if self._names():
            return self._n_partial()
        if digits is not None or (prec is not None and int(prec) != 53):
            # any precision: _sage_real evaluates the expression tree
            import _sage_real
            return _sage_real.N(self, prec, digits)
        re, im = _call("n", _lower_special(self._s))
        re, im = float(re), float(im)
        if im == 0:
            from _sage_lang import RealNumber
            if re == re and not _NORMAL_MIN < abs(re) < _INF:
                # an infinity, a zero or a subnormal double: RR's value may
                # be past the doubles (n(exp(1000))), so the expression is
                # evaluated in the 53-bit MP field, operation by operation as
                # Sage evaluates it in RR (n(pi^-700) is RR(pi)^-700); where
                # that is not available, an error rather than a wrong value
                import _sage_real
                import _sage_lang
                from sage_all import RR
                try:
                    # (in RR's own MP field, whose arithmetic stays MP)
                    v = _sage_real.evaluate(self, 53, _sage_lang._rr_mp())
                except NotImplementedError as err:
                    if _re.search(r"(?:^|\{)z", self._s):
                        # (with a complex number in it, the expression is
                        # CC's, whose numbers are doubles: as before)
                        return RealNumber(re)
                    raise NotImplementedError("the value of %s in RR (the doubles give %r): %s" % (self, re, err))
                if not isinstance(v, _sage_real.RealNumberMP):
                    raise NotImplementedError("the value of %s in RR: the doubles give %r, the MP evaluation %s" % (self, re, v))
                return RR(v)
            return RealNumber(re)
        from _sage_matrix import ComplexNumber
        return ComplexNumber(re, im)

    def _n_partial(self):
        # numerical approximation of the constants of an expression with variables
        ops = self._op()
        tag = ops[0]
        if tag in ("symbol",):
            return self
        if tag in ("rational", "complex", "float", "constant"):
            return _expr(self.n())
        kids = [Expression(s)._n_partial() if Expression(s)._names() else _expr(Expression(s).n()) for s in ops[1:]]
        if tag == "add":
            r = kids[0]
            for k in kids[1:]:
                r = r + k
            return r
        if tag == "mul":
            r = kids[0]
            for k in kids[1:]:
                r = r * k
            return r
        if tag == "pow":
            return kids[0] ** kids[1]
        if tag.startswith("fun:"):
            return _one("fun", tag[4:], *[k._s for k in kids])
        return self

    numerical_approx = N = n

    def __float__(self):
        if self._names():
            raise TypeError("unable to simplify to float approximation")
        re, im = _call("n", _lower_special(self._s))
        if float(im) != 0:
            raise TypeError("unable to simplify to float approximation")
        return float(re)

    def __complex__(self):
        if self._names():
            raise TypeError("unable to simplify to complex approximation")
        re, im = _call("n", _lower_special(self._s))
        return complex(float(re), float(im))

    def __int__(self):
        v = _py_number(self._s)
        if v is None:
            return int(float(self))
        return int(v)

    def _integer_(self, ZZ=None):
        v = _py_number(self._s)
        if isinstance(v, int):
            return v
        raise TypeError("unable to convert %s to an integer" % self)

    def _rational_(self):
        v = _py_number(self._s)
        if v is None or isinstance(v, float):
            raise TypeError("unable to convert %s to a rational" % self)
        return v

    def pyobject(self):
        """The Python number the (numeric) expression is.

        EXAMPLES::

            sage: SR(5).pyobject(), SR(2/3).pyobject()
            (5, 2/3)
        """
        v = _py_number(self._s)
        if v is None:
            raise TypeError("self must be a numeric expression")
        return v

    def _fast_callable(self, names=None):
        """A Python function of the variables (in sorted order) computing this
        expression in floating point (for plots)."""
        names = list(names) if names is not None else (self._names() or ["x"])  # a constant: f(x) = c
        if self._fast is None or self._fast[0] != names:
            src = "lambda %s: %s" % (", ".join("_v_" + n for n in names), _call("pysrc", self._s)[0])
            self._fast = (names, eval(src, _FAST_GLOBALS))
        return self._fast[1]

    # --- calculus
    def diff(self, *args):
        """diff(x), diff(x, 2), diff(x, y), diff(x, 2, y, 3); with no
        argument, in the only variable.

        EXAMPLES::

            sage: (x^3).diff(x), sin(x^2).diff(x), (x^4).diff(x, 2), (x^2*x).derivative(x)
            (3*x^2, 2*x*cos(x^2), 12*x^2, 3*x^2)
            sage: y = var('y'); (x^2*y).diff([x, y]), (x^2).diff([])
            (2*x, x^2)
        """
        # a list alone is the list of variables, and an empty one means no
        # differentiation, as in Sage (diff(x^2, []) was 2*x); a tuple, or a
        # list among other arguments, is Sage's TypeError
        if len(args) == 1 and isinstance(args[0], list):
            if not args[0]:
                return self
            args = tuple(args[0])
        for a in args:
            if isinstance(a, (list, tuple)):
                raise TypeError("no canonical coercion from %s to Symbolic Ring" % type(a))
        if not args:
            names = self._names()
            if len(names) != 1:
                raise ValueError("No differentiation variable specified.")
            args = (Expression(_sym_s(names[0])),)
        r, last = self, None
        for a in args:
            if isinstance(a, int) and not isinstance(a, bool):
                if last is None:
                    raise ValueError("No differentiation variable specified.")
                if a > 1:
                    r = _one("diff", r._s, last, str(a - 1))
                last = None
                continue
            last = _var_name(a)
            r = _one("diff", r._s, last, "1")
        return r

    derivative = differentiate = diff

    def sum(self, *args, **kw):
        """The symbolic sum over a variable: f.sum(k, a, b).

        EXAMPLES::

            sage: var('k n'); (k^2).sum(k, 1, n)
            (k, n)
            1/3*n^3 + 1/2*n^2 + 1/6*n
        """
        return symbolic_sum(self, *args, **kw)

    def gradient(self, vars=None):
        """The gradient (in the variables, or the given ones).

        EXAMPLES::

            sage: var('y')
            y
            sage: (x^2*y).gradient()
            (2*x*y, x^2)
        """
        from _sage_matrix import vector
        vs = vars or self.variables()
        return vector([self.diff(v) for v in vs])

    def hessian(self):
        """The Hessian matrix.

        EXAMPLES::

            sage: var('y')
            y
            sage: (x^2*y).hessian()
            [2*y 2*x]
            [2*x   0]
        """
        from _sage_matrix import matrix
        vs = self.variables()
        return matrix([[self.diff(u).diff(v) for v in vs] for u in vs])

    def taylor(self, *args):
        """taylor(x, a, n) or taylor((x, a), (y, b), n) (one variable here).

        EXAMPLES::

            sage: exp(x).taylor(x, 0, 4), sin(x).taylor(x, pi, 3)
            (1/24*x^4 + 1/6*x^3 + 1/2*x^2 + x + 1, 1/6*(x - pi)^3 - x + pi)
        """
        if len(args) == 3:
            v, a, n = args
        elif len(args) == 2 and isinstance(args[0], (tuple, list)):
            (v, a), n = args
        else:
            raise ValueError("taylor(x, a, n): expected a variable, a point and an order")
        return _one("taylor", self._s, _var_name(v), _expr(a)._s, str(int(n)))

    def series(self, v, n):
        """The series to order n (in x - a for v = (x == a)), with an O-term.

        EXAMPLES::

            sage: sin(x).series(x, 6), (1/(1 - x)).series(x, 4)
            (1*x + (-1/6)*x^3 + 1/120*x^5 + Order(x^6), 1 + 1*x + 1*x^2 + 1*x^3 + Order(x^4))
        """
        if isinstance(v, Expression) and v.is_relational():
            var, a = v.lhs(), v.rhs()
        else:
            var, a = v, 0
        t = self.taylor(var, a, int(n) - 1)
        return _SeriesExpr(t, _expr(var), _expr(a), int(n))

    def limit(self, *args, dir=None, **kw):
        """limit(x=a), limit(x=a, dir='+'), limit(x == a).

        EXAMPLES::

            sage: (sin(x)/x).limit(x=0), (1/x).limit(x=0, dir='+'), ((1 + 1/x)^x).limit(x=oo)
            (1, +Infinity, e)
        """
        if kw:
            if len(kw) != 1:
                raise ValueError("call the limit function like this, e.g. limit(expr, x=2).")
            (v, a), = kw.items()
        elif len(args) == 1 and isinstance(args[0], Expression) and args[0].is_relational():
            v, a = _var_name(args[0].lhs()), args[0].rhs()
        elif len(args) == 2:
            v, a = _var_name(args[0]), args[1]
        else:
            raise ValueError("call the limit function like this, e.g. limit(expr, x=2).")
        d = {None: "", "+": "+", "plus": "+", "right": "+", "above": "+",
             "-": "-", "minus": "-", "left": "-", "below": "-"}.get(dir)
        if d is None:
            raise ValueError("dir must be one of None, 'plus', '+', 'above', 'right', 'minus', '-', 'below', 'left'")
        return _one("limit", self._s, v, _expr(a)._s, d)

    limit_ = limit

    def solve(self, v, **kw):
        """The solutions of the equation (or of expression == 0).

        EXAMPLES::

            sage: (x^2 - 4).solve(x), (x^2 == 2).solve(x)
            ([x == -2, x == 2], [x == -sqrt(2), x == sqrt(2)])
        """
        return solve(self, v, **kw)

    def roots(self, x=None, ring=None, multiplicities=True):
        """The roots of a polynomial equation with multiplicities, [(root, m), ...].

        EXAMPLES::

            sage: (x^2 - 1).roots(), ((x - 1)^2*(x + 2)).roots()
            ([(-1, 1), (1, 1)], [(-2, 1), (1, 2)])
        """
        x = x if x is not None else self.variables()[0]
        f = self.lhs() - self.rhs() if self.is_relational() else self
        if _call("is_zero", f._s)[0] == "1":
            # (the multiplicity loop differentiated 0 forever: CSOL-F12)
            raise ValueError("every value is a root of 0")
        out = []
        sols = solve(f == 0, x)
        # roots are values: a family or a solution valid only under
        # conditions is not one (sin(x).roots() gave []: CSOL-F11); for a
        # polynomial in x, the roots over the field of its parameters (the
        # coefficient-nonzero ones; its a == 0 branches are other polynomials)
        poly = f.is_polynomial(x)
        if any(isinstance(s, Solution) and (s._params or (s._conds and not poly)) for s in sols):
            raise NotImplementedError("roots: the solutions of %s == 0 are families or conditional (see solve())" % f)
        for s in sols:
            # an unresolved 0 == f is no root (x^5 + x + 3 gave (x^5 + x + 3,
            # 1): the systematic review's R2-SYMALG-F3)
            if str(s.lhs()) != str(x):
                raise RuntimeError("no explicit roots found")
            # the roots of the polynomial over the field of its parameters,
            # where a nonzero coefficient is nonzero: those valid while the
            # leading coefficient is nonzero, not the special cases a == 0
            conds = s.conditions() if isinstance(s, Solution) else []
            if any(c._op()[0] != "rel:Ne" for c in conds) or (isinstance(s, Solution) and s._params):
                continue
            r, m = s.rhs(), 0
            g = f
            while True:
                g2 = g.diff(x) if m else g
                if not bool(g2.subs({x: r}) == 0):
                    break
                g, m = g2, m + 1
            out.append((r, max(m, 1)))
        if not multiplicities:
            return [r for r, _ in out]
        return out

    def find_root(self, a, b, var=None):
        """A numerical root in [a, b] (Brent's method).

        EXAMPLES::

            sage: (x^2 - 2).find_root(0, 2)
            1.4142135623731364
        """
        return find_root(self, a, b, var)

    def integrate(self, *args, **kw):
        """The integral: integrate(x), or the definite integral integrate(x, a, b).

        EXAMPLES::

            sage: (x^2).integrate(x), (x^2).integrate(x, 0, 1), exp(-x^2).integral(x, -oo, oo)
            (1/3*x^3, 1/3, sqrt(pi))
        """
        return integrate(self, *args, **kw)

    integral = integrate

    def plot(self, *args, **kw):
        """A plot of the expression (as plot(f, ...)).

        EXAMPLES::

            sage: sin(x).plot((x, 0, 2*pi))  # random
        """
        from sage_plot import plot
        return plot(self, *args, **kw)

    # --- algebra
    def expand(self):
        """The expansion of products and powers.

        EXAMPLES::

            sage: ((x + 1)^3).expand()
            x^3 + 3*x^2 + 3*x + 1
        """
        if self.is_relational():
            return self._map_rel("expand")
        return _one("expand", self._s)

    def _map_rel(self, op):
        tag = _relop(self._op()[0][4:])
        return _one("rel", tag, _call(op, self.lhs()._s)[0], _call(op, self.rhs()._s)[0])

    def factor(self):
        """The factorization (over QQ).

        EXAMPLES::

            sage: (x^4 - 1).factor(), (x^2 - 2).factor()
            ((x^2 + 1)*(x + 1)*(x - 1), x^2 - 2)
        """
        return _one("factor", self._s)

    def simplify(self):
        """Simplify.

        EXAMPLES::

            sage: (x + x).simplify(), (x^2/x).simplify()
            (2*x, x)
        """
        return self  # Sage's simplify() only applies Maxima's simplification

    def simplify_full(self):
        """Full simplification (also full_simplify).

        EXAMPLES::

            sage: (sin(x)^2 + cos(x)^2).simplify_full()
            1
        """
        if self.is_relational():
            return self._map_rel("simplify_full")
        return _one("simplify_full", self._s)

    full_simplify = simplify_full

    def simplify_rational(self):
        """Simplify as a rational function (also rational_simplify).

        EXAMPLES::

            sage: ((x^2 - 1)/(x + 1)).simplify_rational()
            x - 1
        """
        return _one("simplify_rational", self._s)

    rational_simplify = simplify_rational

    def simplify_trig(self):
        """Simplify trigonometric expressions (also trig_simplify).

        EXAMPLES::

            sage: (sin(x)^2 + cos(x)^2).simplify_trig(), (2*sin(x)*cos(x)).trig_simplify()
            (1, 2*cos(x)*sin(x))
        """
        return _one("simplify_trig", self._s)

    trig_simplify = simplify_trig

    def expand_trig(self, full=False, half_angles=False, plus=True, times=True):
        """sin, cos, tan (and sinh, cosh, tanh) of sums and of integer
        multiples by the addition and multiple-angle formulas (also
        trig_expand).  One level, as Sage; full=True repeats it.

        EXAMPLES::

            sage: var('y')
            y
            sage: sin(2*x).expand_trig(), cos(x + y).expand_trig()
            (2*cos(x)*sin(x), cos(x)*cos(y) - sin(x)*sin(y))
            sage: sin(2*x + y).expand_trig()
            cos(y)*sin(2*x) + cos(2*x)*sin(y)
            sage: sin(2*x + y).expand_trig(full=True)
            2*cos(x)*cos(y)*sin(x) + (cos(x)^2 - sin(x)^2)*sin(y)
        """
        if half_angles or not plus or not times:
            raise NotImplementedError("expand_trig with half_angles, plus=False or times=False is not implemented in sagebrush yet")
        r = _one("expand_trig", self._s)
        if full:
            for _ in range(50):
                s = _one("expand_trig", r._s)
                if s._s == r._s:
                    break
                r = s
        return r

    trig_expand = expand_trig

    def reduce_trig(self, var=None):
        """Products and powers of sin and cos (and sinh, cosh) as sums of
        sines and cosines of combined arguments (also trig_reduce).

        EXAMPLES::

            sage: (sin(x)^2).reduce_trig(), (cos(x)^2).reduce_trig()
            (-1/2*cos(2*x) + 1/2, 1/2*cos(2*x) + 1/2)
            sage: (sin(x)^2 + cos(x)^2).reduce_trig(), (sin(x)*cos(x)).trig_reduce()
            (1, 1/2*sin(2*x))
        """
        if var is not None:
            raise NotImplementedError("reduce_trig(var) is not implemented in sagebrush yet")
        return _one("reduce_trig", self._s)

    trig_reduce = reduce_trig

    def expand_log(self, algorithm="products"):
        """log of a product as a sum of logs and log(b^p) as p*log(b)
        (algorithm='powers': only the latter; also log_expand).

        EXAMPLES::

            sage: var('y')
            y
            sage: log(x*y).expand_log(), log(x^10).expand_log(), log(x/y).log_expand()
            (log(x) + log(y), 10*log(x), log(x) - log(y))
            sage: log(x^2*y).expand_log(algorithm='powers')
            log(x^2*y)
        """
        if algorithm == "nothing":
            return self
        if algorithm not in ("products", "powers", "all"):
            raise ValueError("algorithm must be 'nothing', 'powers', 'products' or 'all'")
        return _one("expand_log", self._s, "powers" if algorithm == "powers" else "products")

    log_expand = expand_log

    def simplify_log(self, algorithm=None):
        """Sums of logs with integer coefficients as one log (also
        log_simplify).

        EXAMPLES::

            sage: var('y')
            y
            sage: (log(x) + log(y)).simplify_log(), (log(x) - 2*log(y)).log_simplify()
            (log(x*y), log(x/y^2))
            sage: (3*log(2)).simplify_log(), (2*log(x)).simplify_log()
            (3*log(2), log(x^2))
        """
        if algorithm not in (None, "one"):
            raise NotImplementedError("simplify_log(algorithm=%r) is not implemented in sagebrush yet" % (algorithm,))
        return _one("simplify_log", self._s)

    log_simplify = simplify_log

    def canonicalize_radical(self):
        """Radicals and logs in one canonical form, choosing branches as
        Sage does (sqrt(x^2) is x: not right for every x).

        EXAMPLES::

            sage: var('y')
            y
            sage: sqrt(x^2*y^2).canonicalize_radical(), sqrt(8*x^3).canonicalize_radical()
            (x*y, 2*sqrt(2)*x^(3/2))
            sage: sqrt(x^2 + 2*x + 1).canonicalize_radical(), log(x*y).canonicalize_radical()
            (x + 1, log(x) + log(y))
        """
        return _one("canonicalize_radical", self._s)

    def simplify_factorial(self):
        """Factorials and gammas whose arguments differ by integers combined
        (also factorial_simplify).

        EXAMPLES::

            sage: var('n')
            n
            sage: (factorial(n + 1)/factorial(n)).simplify_factorial()
            n + 1
            sage: (gamma(n + 1)/gamma(n)).factorial_simplify()
            n
        """
        return _one("simplify_factorial", self._s)

    factorial_simplify = simplify_factorial

    def partial_fraction(self, var=None):
        """The partial fraction decomposition in var, a rational function
        with rational coefficients.

        EXAMPLES::

            sage: (1/(x^2 - 1)).partial_fraction()
            -1/2/(x + 1) + 1/2/(x - 1)
            sage: (1/(x^2 + 1)).partial_fraction(x)
            1/(x^2 + 1)
        """
        name = self._default_var() if var is None else _expr(var)._names()[0] if not isinstance(var, str) else var
        return _one("partial_fraction", self._s, name)

    def collect(self, s):
        """The expanded expression with its terms grouped by the power of s.

        EXAMPLES::

            sage: var('a b')
            (a, b)
            sage: (x^2 + a*x^2 + b*x + x + 1).collect(x)
            (a + 1)*x^2 + (b + 1)*x + 1
            sage: (a*sin(x) + b*sin(x)).collect(sin(x))
            (a + b)*sin(x)
        """
        s = _expr(s)
        if not s.is_symbol():
            # a subexpression: through a fresh symbol
            names = set(self._names()) | set(s._names())
            k = 0
            while "_collect%d" % k in names:
                k += 1
            t = Expression(_sym_s("_collect%d" % k))
            return self.subs({s: t}).collect(t).subs({t: s})
        e = self.expand()
        terms = e.operands() if e._op()[0] == "add" else [e]
        groups, order = {}, []
        for t in terms:
            # the term's factor s^k (k an integer, else 0); the rest is its
            # coefficient, whatever else it contains (x*sin(x): sin(x))
            fs = t.operands() if t._op()[0] == "mul" else [t]
            k, cs = 0, []
            for f in fs:
                if f._s == s._s:
                    k += 1
                    continue
                if f._op()[0] == "pow":
                    b, p = f.operands()
                    if b._s == s._s and p.is_integer():
                        k += int(p)
                        continue
                cs.append(f)
            c = Expression("n1/1;")
            for f in cs:
                c = c * f
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(c)
        r = Expression("n0/1;")
        for k in order:
            c = Expression("n0/1;")
            for u in groups[k]:
                c = c + u
            r = r + c * s ** k
        return r

    def combine(self):
        """Combine the terms of a sum that have the same denominator (Sage's
        combine(); together() puts everything over one denominator).

        EXAMPLES::

            sage: (1/x + 1/(x + 1)).combine()
            1/(x + 1) + 1/x
        """
        if self._op()[0] != "add":
            return self
        groups = {}
        order = []
        for t in self.operands():
            n, d = t.numerator_denominator()
            k = repr(d)
            if k not in groups:
                groups[k] = [d, []]
                order.append(k)
            groups[k][1].append(n)
        out = 0
        for k in order:
            d, ns = groups[k]
            num = ns[0]
            for n in ns[1:]:
                num = num + n
            out = out + (num if repr(d) == "1" else num / d)
        return out

    def numerator(self):
        """The numerator.

        EXAMPLES::

            sage: ((x + 1)/(x - 1)).numerator()
            x + 1
        """
        return _one("numerator", self._s)

    def denominator(self):
        """The denominator.

        EXAMPLES::

            sage: ((x + 1)/(x - 1)).denominator()
            x - 1
        """
        return _one("denominator", self._s)

    def numerator_denominator(self):
        """(numerator, denominator).

        EXAMPLES::

            sage: ((x + 1)/(x - 1)).numerator_denominator()
            (x + 1, x - 1)
        """
        return self.numerator(), self.denominator()

    def degree(self, x):
        """The degree in x.

        EXAMPLES::

            sage: (x^5 + x).degree(x)
            5
        """
        return int(_call("degree", self._s, _var_name(x))[0])

    def coefficient(self, x, n=1):
        """The coefficient of x^n.

        EXAMPLES::

            sage: f = 3*x^2 + 2*x + 1
            sage: f.coefficient(x, 2), f.coefficient(x), f.coeff(x, 0)  # sagebrush only
            (3, 2, 1)
        """
        return _one("coefficient", self._s, _var_name(x), str(int(n)))

    coeff = coefficient

    def list(self, x=None):
        """The coefficients of a polynomial in x, constant term first.

        EXAMPLES::

            sage: (3*x^2 + 1).list(x)
            [1, 0, 3]
        """
        x = _var_name(x if x is not None else self._default_var())
        return [Expression(s) for s in _call("coefficients", self._s, x)]

    def coefficients(self, x=None, sparse=True):
        """[[c, n], ...] for the nonzero terms c*x^n (sparse=False: list()).

        EXAMPLES::

            sage: (3*x^2 + 1).coefficients()
            [[1, 0], [3, 2]]
        """
        cs = self.list(x)
        if not sparse:
            return cs
        return [[c, i] for i, c in enumerate(cs) if not c.is_trivial_zero()]

    def _default_var(self):
        names = self._names()
        if not names:
            return "x"
        return names[0]

    def polynomial(self, base_ring=None, ring=None):
        """This expression as a polynomial (Sage's f.polynomial(QQ)).

        EXAMPLES::

            sage: (x^2 + 3*x + 1).polynomial(QQ), (x^2 + 3*x + 1).polynomial(QQ).parent()
            (x^2 + 3*x + 1, Univariate Polynomial Ring in x over Rational Field)
        """
        import sage_all as sa
        names = self._names()
        if len(names) > 1:
            raise NotImplementedError("polynomials in several variables")
        if ring is None:
            ring = sa.PolynomialRing(base_ring if base_ring is not None else sa.QQ, names[0] if names else "x")
        cs = []
        for c in self.list(names[0] if names else "x"):
            v = _py_number(c._s)
            if v is None or isinstance(v, float):
                raise TypeError("%s is not a polynomial with exact coefficients" % self)
            cs.append(v)
        t, r = ring.gen(), ring(0)
        for i, c in enumerate(cs):
            if c:
                r = r + ring(c) * t ** i
        return r

    def power_series(self, base_ring=None):
        """The expression as a power series (its Taylor series).

        EXAMPLES::

            sage: exp(x).series(x, 5)
            1 + 1*x + 1/2*x^2 + 1/6*x^3 + 1/24*x^4 + Order(x^5)
        """
        raise NotImplementedError("power_series")

    def real(self):
        """The real part.

        EXAMPLES::

            sage: (3 + 4*I).real(), (3 + 4*I).real_part()
            (3, 3)
        """
        return _real_imag(self, 0)

    def imag(self):
        """The imaginary part.

        EXAMPLES::

            sage: (3 + 4*I).imag(), (3 + 4*I).imag_part()
            (4, 4)
        """
        return _real_imag(self, 1)

    real_part, imag_part = real, imag

    def conjugate(self):
        """The complex conjugate.

        EXAMPLES::

            sage: (1 + I).conjugate(), (2 - 3*I).conjugate()
            (-I + 1, 3*I + 2)
        """
        return self.real() - Expression(_call("const", "I")[0]) * self.imag()

    def abs(self):
        """The absolute value.

        EXAMPLES::

            sage: abs(-x), (-3*x).abs()
            (abs(x), 3*abs(x))
        """
        return abs(self)

    def sqrt(self):
        """The square root.

        EXAMPLES::

            sage: (x^2).sqrt(), SR(4).sqrt()
            (sqrt(x^2), 2)
        """
        return self ** _Fraction(1, 2)

    def exp(self):
        """e to the expression.

        EXAMPLES::

            sage: x.exp(), (0*x).exp()
            (e^x, 1)
        """
        return _one("fun", "exp", self._s)

    def log(self, b=None):
        """The natural logarithm.

        EXAMPLES::

            sage: x.log(), e.log()
            (log(x), 1)
        """
        r = _one("fun", "log", self._s)
        return r if b is None else r / _one("fun", "log", _expr(b)._s)

    def show(self):
        """Show the expression typeset (LaTeX in a notebook).

        EXAMPLES::

            sage: (x^2/2).show()  # random
        """
        show_typeset(self)



Expression.__module__ = "sage.symbolic.expression"
Expression._defined_in = "_sage_expr"

def _real_imag(e, k):
    # exact for numbers; otherwise numerical when the expression is constant
    if e._names():
        raise NotImplementedError("real and imaginary parts of expressions with variables")
    r = _call("number", e._s)
    if r[0] == "q":
        return e if k == 0 else Expression("n0/1;")
    if r[0] == "z":
        return Expression("n%s;" % r[1 + k])
    c = complex(e)
    return _expr(c.imag if k else c.real)


class Typeset:
    """What show(...) displays: typeset math where the page or Jupyter
    can render LaTeX, the text form elsewhere (several objects separated
    by spaces).  (Values print as text, as in Sage.)

    EXAMPLES::

        sage: from _sage_expr import show_typeset  # sagebrush only
        sage: show_typeset(x^2)  # random  # sagebrush only
        x^2
        sage: from _sage_expr import Typeset  # sagebrush only
        sage: Typeset(1, 2/3)._repr_mimebundle_()["text/latex"]  # sagebrush only
        '$$1 \\\\ \\\\frac{2}{3}$$'
    """

    def __init__(self, *objs):
        self._objs = objs

    def __repr__(self):
        return self._plain()

    def _repr_latex_(self):
        with _display_budget.display():
            parts = [latex(o) for o in self._objs]
            _charge(1, 4 + 3 * len(parts), "a _latex_")
            return "$$" + " \\ ".join(parts) + "$$"

    def _plain(self):
        # (each piece charged before it is joined: _repr_charged)
        with _display_budget.display():
            parts = []
            for o in self._objs:
                parts.append(_repr_charged(o, ()))
            _charge(1, len(parts))
            return " ".join(parts)

    def _repr_mimebundle_(self, include=None, exclude=None):
        # the marker: the notebook typesets what show() asked for, and
        # leaves other values with a LaTeX form (2/3) as text, as Sage.
        # One display: both forms built within one budget (LIMIT-SHOW87-2)
        with _display_budget.display():
            return {"text/latex": self._repr_latex_(), "text/plain": self._plain(),
                    "application/vnd.sagebrush.typeset": "1"}


def show_typeset(*objs):
    """Show objs typeset with LaTeX: one display (its text form where the
    host cannot typeset).

    EXAMPLES::

        sage: from _sage_expr import show_typeset  # sagebrush only
        sage: show_typeset(sqrt(x)/2)  # random  # sagebrush only
        1/2*sqrt(x)
    """
    import builtins
    t = Typeset(*objs)
    d = getattr(builtins, "__pyjs_display__", None)
    if d is not None:
        d(t)  # (it prints the text form itself without a notebook)
        return
    from _graphics import host_display
    if not host_display(t):
        print(repr(t))


def _min_order(a, b):
    """The smaller of two series orders, None meaning exact."""
    return b if a is None else a if b is None else min(a, b)


class _SeriesExpr(Expression):
    """A truncated series: prints the polynomial part plus O(x^n)."""

    __slots__ = ("_var", "_at", "_order")

    def __init__(self, t, var, at, order):
        Expression.__init__(self, t._s)
        self._var, self._at, self._order = var, at, order

    def _laurent(self):
        """(N, [c_0, c_1, ...]): the body is sum c_i (x - a)^(i - N)."""
        v, a = self._var, self._at
        body = Expression(self._s).subs({v: v + a}).expand()
        for N in range(0, 2000):
            try:
                return N, (body * v ** N).expand().list(v) if N else body.list(v)
            except ValueError:
                continue
        raise ValueError("not a Laurent polynomial")

    def _valuation(self):
        N, cs = self._laurent()
        for i, c in enumerate(cs):
            if not c.is_trivial_zero():
                return i - N
        return self._order if self._order is not None else 10**9

    def _same(self, o):
        if isinstance(o, _SeriesExpr):
            if str(o._var) != str(self._var) or str(o._at) != str(self._at):
                raise ValueError("series in different variables or at different points")
            return o
        o = _expr(o)
        if str(self._var) not in o._names():
            return None  # a constant: exact
        a = self._at
        try:
            # a polynomial in (x - a): exact, with no O-term of its own
            o.subs({self._var: self._var + a}).expand().list(self._var)
            return _SeriesExpr(o, self._var, a, None)
        except ValueError:
            return o.series(self._var == a if not a.is_trivial_zero() else self._var, self._order)

    def _make(self, body, order):
        v, a = self._var, self._at
        # keep only the terms below the order
        t = _SeriesExpr(_expr(body), v, a, order)
        N, cs = t._laurent()
        if order is None:
            return _expr(body)
        keep = sum((c * (v - a) ** (i - N) for i, c in enumerate(cs) if i - N < order and not c.is_trivial_zero()), _expr(0))
        return _SeriesExpr(keep, v, a, order)

    # arithmetic keeps the O-term (a truncated series determines its
    # products only to the lower precision)
    def __add__(self, o):
        t = self._same(o)
        if t is None:
            return self._make(Expression(self._s) + _expr(o), self._order)
        return self._make(Expression(self._s) + Expression(t._s), _min_order(self._order, t._order))

    __radd__ = __add__

    def __neg__(self):
        return _SeriesExpr(-Expression(self._s), self._var, self._at, self._order)

    def __sub__(self, o):
        return self + (-(self._same(o) if self._same(o) is not None else _expr(o)))

    def __rsub__(self, o):
        return (-self) + o

    def __mul__(self, o):
        t = self._same(o)
        if t is None:
            c = _expr(o)
            if c.is_trivial_zero():
                return c
            return self._make(Expression(self._s) * c, self._order)
        order = _min_order(None if self._order is None else self._order + t._valuation(),
                           None if t._order is None else t._order + self._valuation())
        return self._make((Expression(self._s) * Expression(t._s)).expand(), order)

    __rmul__ = __mul__

    def expand(self):
        """The series itself (expanded, with its O-term)."""
        return self

    # (the systematic review's R2-SYMALG-F8: s^(3/2) was s, 1/s, diff(s),
    # s.subs(...), s.simplify_full() dropped the O-term, and dividing by
    # 1 + O(x) kept O(x^5))
    def __pow__(self, k):
        from fractions import Fraction
        kq = _py_number(_expr(k)._s)
        if kq is None or isinstance(kq, (float, complex)):
            raise NotImplementedError("series: only rational powers")
        kq = Fraction(kq)
        if kq.denominator == 1 and kq >= 1:
            r = self
            for _ in range(int(kq) - 1):
                r = r * self
            return r
        if kq == 0:
            return _expr(1)
        if self._order is None:
            return _expr(Expression(self._s) ** _expr(k))
        # (t^v u)^k with u known to t^(n - v): t^(v k) u^k, known to as many
        # terms; v k must be an integer, and u's constant term not 0
        v = self._valuation()
        if v >= self._order:
            raise ZeroDivisionError("series: a power of a series that is O(x^%d)" % self._order) if kq < 0 else NotImplementedError("series: a power of O(x^n)")
        vk = v * kq
        if vk.denominator != 1:
            raise NotImplementedError("series: the power is not a Laurent series (Puiseux)")
        order = int(vk) + (self._order - v)
        body = Expression(self._s) ** _expr(k)
        at = self._at
        s2 = body.series(self._var == at if not at.is_trivial_zero() else self._var, order)
        return _SeriesExpr(s2, self._var, at, order) if not isinstance(s2, _SeriesExpr) else _SeriesExpr(Expression(s2._s), self._var, at, order)

    def __truediv__(self, o):
        if isinstance(o, _SeriesExpr):
            return self * (self._same(o) ** -1)
        o = _expr(o)
        if str(self._var) in o._names():
            t = self._same(o)
            return self * (t ** -1) if isinstance(t, _SeriesExpr) else self._make(Expression(self._s) / o, self._order)
        return self._make(Expression(self._s) / o, self._order)

    def __rtruediv__(self, o):
        return _expr(o) * (self ** -1) if not isinstance(o, _SeriesExpr) else o * (self ** -1)

    def diff(self, *args):
        """The derivative: one order less for each differentiation in the
        series variable (SERIES-0AF-1: diff([x]) kept O(x^5)).

        EXAMPLES::

            sage: s = exp(x).series(x, 5); s.diff(), s.diff([x]), s.diff(x, 2), s.diff(x, x)
            (1 + 1*x + 1/2*x^2 + 1/6*x^3 + Order(x^4), 1 + 1*x + 1/2*x^2 + 1/6*x^3 + Order(x^4), 1 + 1*x + 1/2*x^2 + Order(x^3), 1 + 1*x + 1/2*x^2 + Order(x^3))
        """
        if len(args) == 1 and isinstance(args[0], (list, tuple)):
            if not args[0]:
                return self  # (no variables: no differentiation, as Sage)
            args = tuple(args[0])
        if not args:
            args = (self._var,)
        # (variable, count) pairs: a count after a variable repeats it
        steps = []
        for a in args:
            if isinstance(a, int) or (isinstance(a, Expression) and a.is_numeric() and not a._names()):
                q = _py_number(_expr(a)._s) if isinstance(a, Expression) else a
                if not isinstance(q, int) or isinstance(q, bool):
                    # a fractional count is not a count (it was truncated:
                    # CORR-EC3-2); Sage's error
                    raise TypeError("argument symb must be a symbol")
                if not steps:
                    raise ValueError("a derivative count needs a variable before it")
                steps[-1] = (steps[-1][0], steps[-1][1] + q - 1)
            else:
                steps.append((a, 1))
        body, order = Expression(self._s), self._order
        for v, n in steps:
            if n < 0:
                raise ValueError("the number of derivatives must be nonnegative")
            if not n:
                continue
            if str(v) == str(self._var):
                # one call with the count (the engine's own), not n calls
                body = body.diff(v, n) if n > 1 else body.diff(v)
                if order is not None:
                    order -= n
            else:
                # another variable: each coefficient is differentiated, the
                # coordinate (x - a) held fixed, as Sage does, and the order
                # kept (the chain rule on x - a gave O((x - a)^3) for a
                # series known to O((x - a)^2): CORR-EC3-3)
                body = self._coeff_diff(body, v, n)
        return self._make(body, order)

    def _coeff_diff(self, body, v, n):
        var, a = self._var, self._at
        N, cs = _SeriesExpr(_expr(body), var, a, self._order)._laurent()
        t = var - a
        return sum((c.diff(v, n) * t ** (i - N) for i, c in enumerate(cs) if not c.is_trivial_zero()), _expr(0))

    derivative = diff

    def subs(self, *args, **kw):
        """Substitution in the coefficients; the series variable only by
        another symbol (else the O-term has no meaning: truncate() first)."""
        d = dict(args[0]) if args and isinstance(args[0], dict) else {}
        for a in args:
            if not isinstance(a, dict) and isinstance(a, Expression) and a.is_relational():
                d[a.lhs()] = a.rhs()
        for k, val in kw.items():
            d[_expr(SR.var(k))] = val
        newvar = self._var
        for k, val in list(d.items()):
            if str(k) == str(self._var):
                val = _expr(val)
                if val._op()[0] != "symbol":
                    raise NotImplementedError("subs: substituting %s for the series variable loses the O-term; use truncate() first" % val)
                newvar = val
        body = Expression(self._s).subs(d)
        return _SeriesExpr(body, newvar, _expr(self._at).subs(d), self._order)

    substitute = subs

    def simplify(self):
        return _SeriesExpr(Expression(self._s).simplify(), self._var, self._at, self._order)

    def simplify_full(self):
        return _SeriesExpr(Expression(self._s).simplify_full(), self._var, self._at, self._order)

    def simplify_rational(self):
        return _SeriesExpr(Expression(self._s).simplify_rational(), self._var, self._at, self._order)

    def _terms(self, latex):
        # Sage's form: ascending powers of (x - a), numeric coefficients
        # written out (1*x) and parenthesized unless positive: (-1/6)*x^3
        v, a = self._var, self._at
        base = v - a
        N, coeffs = self._laurent()
        out = []
        for i, c in enumerate(coeffs):
            i -= N
            if c.is_trivial_zero():
                continue
            cs = c._latex_() if latex else str(c)
            if not (c.is_numeric() and bool(c > 0)):
                cs = ("\\left(%s\\right)" if latex else "(%s)") % cs
            if i == 0:
                out.append(cs)
                continue
            p = base if i == 1 else base ** i
            ps = p._latex_() if latex else str(p)
            if i < 0:
                b = base._latex_() if latex else str(base)
                if not base.is_symbol():
                    b = "(%s)" % b
                ps = ("%s^{%d}" if latex else "%s^(%d)") % (b, i)
            if i == 1 and not base.is_symbol():
                ps = ("\\left(%s\\right)" if latex else "(%s)") % ps
            out.append(cs + (" " if latex else "*") + ps)
        h = base ** self._order
        hs = h._latex_() if latex else str(h)
        out.append(("\\mathcal{O}\\left(%s\\right)" if latex else "Order(%s)") % hs)
        return " + ".join(out)

    def __repr__(self):
        return self._terms(False)

    __str__ = __repr__

    def _latex_(self):
        return self._terms(True)

    def truncate(self):
        """The series without its O(x^n) term.

        EXAMPLES::

            sage: sin(x).series(x, 6).truncate()
            1/120*x^5 - 1/6*x^3 + x
        """
        return Expression(self._s)


class _SymbolicRing:
    """The symbolic ring, SR: expressions in variables and constants (pi, e,
    sqrt(2), sin(x), ...), kept exact and simplified on request.

    SR(v) makes a symbolic expression from a number or a string; SR.var('t')
    makes a variable without binding a name.  x is predefined; var('y')
    declares more.

    EXAMPLES::

        sage: SR
        Symbolic Ring
        sage: SR(1)/3 + x, sin(x).parent()
        (x + 1/3, Symbolic Ring)
        sage: SR(pi).n(digits=10), sqrt(SR(8))
        (3.141592654, 2*sqrt(2))
        sage: t = SR.var('t'); (t^2 - 1).factor()
        (t + 1)*(t - 1)
    """

    def __repr__(self):
        return "Symbolic Ring"

    def __reduce__(self):
        # (one SR: a pickle or a copy of it is SR itself, as in Sage)
        return "SR_parent"

    def __call__(self, v):
        """Convert v into a symbolic expression.

        EXAMPLES::

            sage: SR(3/4), SR(pi)
            (3/4, pi)
        """
        return _expr(v)

    def var(self, *names, **kw):
        """Symbolic variables: SR.var('t') (not injected into the globals).

        EXAMPLES::

            sage: t = SR.var('t'); t^2
            t^2
            sage: u = SR.var('u', domain='real'); assumptions()
            [u is real]
            sage: forget()
        """
        if len(names) == 1 and isinstance(names[0], (list, tuple)):
            names = tuple(names[0])
        if len(names) == 1 and isinstance(names[0], str):
            names = names[0].replace(",", " ").split()
        vs = tuple(Expression(_sym_s(n)) for n in names)
        if kw.get("latex_name") is not None:
            for n in names:
                _LATEX_NAMES[n] = str(kw["latex_name"])
        if kw.get("domain") in ("positive", "integer", "real", "complex"):
            for v in vs:
                assume(v, kw["domain"])
        return vs[0] if len(vs) == 1 else vs

    def _latex_(self):
        return "\\text{SR}"


SR_parent = _SymbolicRing()
SR = SR_parent


def _var_name(v):
    if isinstance(v, str):
        return v
    if isinstance(v, Expression) and v.is_symbol():
        return _call("str", v._s)[0]
    if _is_poly(v):
        return v.variable_name()
    raise TypeError("%s is not a valid variable." % (v,))


# ------------------------------------------------------------------ special functions
#
# The numerical values of the special functions (gamma, erf, psi, zeta,
# ...) come from lib/_special.py, the numerical core that MATLAB mode and
# scipy.special share; the engine knows their exact values, canonical
# forms and derivatives (engine/sym special.rs) and leaves a call with
# float arguments as a call, which _complete_special evaluates here.

import re as _re
import cmath as _cmath


class _LazySpecial:
    """lib/_special.py, imported when first used: it needs numpy, which the
    CPython package (sagebrush.sage) does not require for the rest of the
    Sage layer."""
    _mod = None

    def __getattr__(self, name):
        m = _LazySpecial._mod
        if m is None:
            try:
                import _special as m
            except ImportError as e:
                raise NotImplementedError("numerical values of special functions need numpy (%s)" % e)
            _LazySpecial._mod = m
        return getattr(m, name)


_sf = _LazySpecial()

_SPECIAL_NAMES = ("gamma", "erf", "psi", "log_gamma", "zeta", "zetaderiv", "hurwitz_zeta", "beta", "erfc", "erfi",
                  "erfinv", "exp_integral_e1", "Ei", "dilog", "polylog", "lambert_w", "elliptic_kc", "elliptic_ec")
_SPECIAL_RE = _re.compile(r"F\d+:(?:%s)\d+\{" % "|".join(_SPECIAL_NAMES))
_FLOAT_RE = _re.compile(r"\{[fg][0-9a-f]")


class _Keep(Exception):
    """Sage leaves this call unevaluated (no value, or one Sagebrush does not
    compute yet)."""


def _int_param(v, what):
    if isinstance(v, complex):
        if v.imag != 0:
            raise _Keep
        v = v.real
    if v != int(v):
        raise _sf.NotCovered("a non-integer %s is not available in sagebrush yet" % what)
    return int(v)


def _below_cut(z):
    """A real z > 1 as z - 0i: on the cut (1, oo) of polylog, Sage gives the
    limit from below (dilog(2.0) = 2.467... - 2.177...*I)."""
    return complex(z, -0.0) if isinstance(z, float) and z > 1 else z


def _bernoulli_even(J):
    """B_2, B_4, ..., B_2J as Fractions."""
    from fractions import Fraction
    from math import comb
    b = [Fraction(1)]
    for m in range(1, 2 * J + 1):
        b.append(-sum(comb(m + 1, k) * b[k] for k in range(m)) / (m + 1))
    return [b[2 * j] for j in range(1, J + 1)]


_EM_B = None


def _expm1(z):
    """e^z - 1 without cancellation for small z, real or complex."""
    if not isinstance(z, complex):
        return _m.expm1(z)
    if abs(z) < 1e-3:
        return z * (1 + z / 2 * (1 + z / 3 * (1 + z / 4 * (1 + z / 5))))
    return _cmath.exp(z) - 1


def _zeta_near0(s):
    """zeta(s) for |s| < 1e-3 (real or complex), by Euler-Maclaurin summation
    (DLMF 25.2.9) with N = 10 and 12 Bernoulli corrections, at s itself:
    _special's reflection through zeta(1 - s) loses s when |s| is tiny
    (1 - s rounds to 1; its error is about eps/|s|, harmless above 1e-3,
    as compared with mpmath).  With k^(-s) = 1 + expm1(-s log k), the integer
    parts of the sum, of N^(1-s)/(s - 1) and of N^(-s)/2 add up to exactly
    -1/2, and every other term is O(s): no cancellation.  The first
    neglected correction, about 2 |s| 24! / ((2 pi)^26 N^25), is below
    1e-22."""
    global _EM_B
    if _EM_B is None:
        _EM_B = [float(x) for x in _bernoulli_even(12)]
    N = 10
    e = [0.0] + [_expm1(-s * _m.log(k)) for k in range(1, N + 1)]
    # sum_(k<N) k^-s + N^(1-s)/(s-1) + N^-s/2 + 1/2
    t = sum(e[1:N]) - N * s / (1 - s) - N * e[N] / (1 - s) + e[N] / 2
    # B_2j/(2j)! s (s + 1) ... (s + 2j - 2) N^(-s-2j+1)
    poch, fact = s, 2.0
    for j, b in enumerate(_EM_B, 1):
        t += b / fact * poch * (1 + e[N]) / N ** (2 * j - 1)
        poch *= (s + 2 * j - 1) * (s + 2 * j)
        fact *= (2 * j + 1) * (2 * j + 2)
    return t - 0.5


def _is_npi(z):
    """Whether z (float or complex) is a nonpositive integer."""
    if isinstance(z, complex):
        if z.imag != 0:
            return False
        z = z.real
    return z <= 0 and z == int(z)


def _beta_complex(a, b):
    """B(a, b) = Gamma(a) (Gamma(b)/Gamma(a + b)) for complex a, b (DLMF
    5.12.1): 0 where only Gamma(a + b) has a pole (it is not divided by),
    and the quotient first, so B(1e-200(1 + i), 1e-200(1 - i)) = 1e200
    does not overflow on the way.  Where a gamma value itself overflows
    (B(90 + i, 90 - i)), NotImplementedError: exp of a sum of log Gammas
    would lose digits in proportion to their size (2e-13 there)."""
    if _is_npi(a) or _is_npi(b):
        raise _sf.PoleError("beta has a pole there")
    if _is_npi(a + b):
        return 0.0
    def g(z):
        # Gamma(z) = Gamma(1 + z)/z near 0, where exp(log Gamma(z)) would
        # turn log Gamma's absolute error (log Gamma is about -log z) into a
        # relative one (3.5e-14 at z = 1e-200(1 + i))
        return _sf.gamma(z + 1) / z if abs(z) < 0.5 else _sf.gamma(z)
    try:
        ga, gb, gs = g(a), g(b), g(a + b)
        r = ga * (gb / gs)
    except (OverflowError, _sf.NotCovered):
        # (_special's complex gamma refuses with NotCovered where |Gamma| leaves the doubles)
        ga = r = float("inf")
        gb = gs = 1.0
    if not all(_cmath.isfinite(v) and v != 0 for v in (ga, gb, gs, r)):
        raise _sf.NotCovered("beta%r: its gamma values leave the double range; not available in sagebrush yet" % ((a, b),))
    return r


def _special_raw(name, a):
    """name(*a) for Python floats or complexes, from _special."""
    if name == "gamma":
        return _sf.gamma(a[0])
    if name == "erf":
        return _sf.erf(a[0])
    if name == "psi":
        return _sf.psi(a[0]) if len(a) == 1 else _sf.polygamma(_int_param(a[0], "n"), a[1])
    if name == "log_gamma":
        return _sf.loggamma(a[0])
    if name == "zeta":
        if abs(a[0]) < 1e-3:
            return _zeta_near0(a[0])
        return _sf.zeta(a[0])
    if name == "hurwitz_zeta":
        if isinstance(a[1], complex):
            raise _sf.NotCovered("hurwitz_zeta at a complex a is not available in sagebrush yet")
        return _sf.hurwitz_zeta(a[0], a[1])
    if name == "beta":
        if any(isinstance(t, complex) for t in a):
            return _beta_complex(a[0], a[1])
        return _sf.beta(a[0], a[1])
    if name in ("erfc", "erfi", "exp_integral_e1"):
        return getattr(_sf, name)(a[0])
    if name == "dilog":
        return _sf.dilog(_below_cut(a[0]))
    if name == "erfinv":
        if isinstance(a[0], complex):
            raise _sf.NotCovered("erfinv at a complex argument is not available in sagebrush yet")
        v = _sf.erfinv(a[0])
        if v != v:
            raise _Keep     # no real value: Sage keeps erfinv(1.5)
        return v
    if name == "Ei":
        if isinstance(a[0], complex):
            raise _sf.NotCovered("Ei at a complex argument is not available in sagebrush yet")
        return _sf.exp_integral_ei(a[0])
    if name == "polylog":
        return _sf.polylog(_int_param(a[0], "s"), _below_cut(a[1]))
    if name == "lambert_w":
        return _sf.lambert_w(a[0]) if len(a) == 1 else _sf.lambert_w(a[1], _int_param(a[0], "k"))
    if name in ("elliptic_kc", "elliptic_ec"):
        m = a[0]
        if isinstance(m, complex) or m > 1:
            raise _sf.NotCovered("%s(m) for m > 1 or complex m is not available in sagebrush yet" % name)
        return (_sf.ellipk if name == "elliptic_kc" else _sf.ellipe)(m)
    raise _sf.NotCovered("%s is not evaluated numerically in sagebrush yet" % name)


class _UnsignedInfinity:
    """Sage's unsigned infinity (gamma at a pole given as a complex number)."""


class _AmbiguousPole(NotImplementedError):
    """A pole whose value in Sage depends on whether the argument is a real or
    a complex number, reached through a symbolic expression, where the
    engine keeps -1.0 + 0.0*I as the real -1.0: refused rather than guessed
    (Sage: gamma(-1.0 + 0.0*I) is Infinity, gamma(SR(-1.0)) NaN)."""


# the functions whose value at a pole, reached through a symbolic
# expression, Sage gives differently for real and complex arguments
# (gamma(SR(-1.0)) NaN, gamma(-1.0 + 0.0*I) Infinity; beta NaN or NaN + NaN*I);
# zeta's (Infinity), log_gamma's (NaN + NaN*I) and hurwitz_zeta's (+infinity)
# are the same both ways there
_KIND_POLES = ("gamma", "beta")


def _is_pole(name, a):
    """Whether the arguments a are a pole of name: _special's PoleError there
    is the function's own, not one met inside a transformation (zeta's
    reflection through zeta(1 - s) at a tiny s, say)."""
    x = a[-1]
    if name in ("gamma", "log_gamma") or name == "psi" and len(a) == 1:
        return _is_npi(x)
    if name == "beta":
        return _is_npi(a[0]) or _is_npi(a[1])
    if name in ("zeta", "hurwitz_zeta"):
        return a[0] == 1
    if name in ("exp_integral_e1", "Ei"):
        return x == 0
    if name in ("polylog", "elliptic_kc"):
        return x == 1
    return False


def _pole_value(name, a, cx):
    """What Sage gives at a pole of name (arguments a, cx: whether each was
    given as a complex number, None when that is unknown: through the
    engine), or _Keep."""
    if not _is_pole(name, a):
        raise _sf.NotCovered("%s%r: _special met a pole of an intermediate step; this point is not available in sagebrush yet" % (name, tuple(a)))
    x = a[-1]
    inf, nan = float("inf"), float("nan")
    if cx is None:
        if name in _KIND_POLES:
            raise _AmbiguousPole("%s(%s) is a pole where Sage's value depends on whether the argument is real or complex, which this expression no longer tells; evaluate %s at a RealNumber or ComplexNumber" % (name, ", ".join(map(repr, a)), name))
        # through an expression Sage gives these as for complex arguments
        cx = [name in ("zeta", "log_gamma")] * len(a)
    if name == "gamma":
        if cx[-1]:
            return _UnsignedInfinity
        return _m.copysign(inf, x) if x == 0 else nan
    if name == "zeta" and cx[0]:
        return _UnsignedInfinity
    if name == "beta":
        return complex(nan, nan) if any(cx) else nan
    if name == "psi" and len(a) == 1:
        return nan
    if name == "log_gamma":
        return inf if x == 0 and not cx[-1] else complex(nan, nan)
    if name in ("zeta", "hurwitz_zeta", "exp_integral_e1", "elliptic_kc"):
        return inf
    if name == "Ei":
        return -inf
    if name == "polylog":
        return complex(nan, nan)
    raise _Keep


def _special_value(name, a, kinds=True):
    """name(*a) at Python floats or complexes as Sage evaluates it: a float
    or complex (Sage's NaN or infinity at a pole); _Keep where Sage keeps
    the call; NotImplementedError (_special.NotCovered) where Sage has a
    value that Sagebrush does not compute.  kinds=False: the arguments come
    from the engine, which does not tell -1.0 + 0.0*I from -1.0, so a pole
    whose value depends on that raises _AmbiguousPole."""
    cx = [isinstance(t, complex) for t in a] if kinds else None
    a = [t.real if isinstance(t, complex) and t.imag == 0 else t for t in a]
    try:
        return _special_raw(name, a)
    except _sf.PoleError:
        return _pole_value(name, a, cx)
    except _sf.NotCovered:
        raise
    except (ValueError, TypeError, OverflowError):
        raise _Keep


def _sp(name, *args):
    """name(*args) for compiled expressions (fast_callable, plots): a float
    or complex, NaN where there is no value."""
    try:
        v = _special_value(name, [complex(t) if isinstance(t, complex) else float(t) for t in args])
    except (_Keep, NotImplementedError):
        return float("nan")
    return float("inf") if v is _UnsignedInfinity else v


def _gamma(x):
    return _sp("gamma", x)


def _num_pair(s):
    """(re, im) of a numeric serialized expression, from the engine."""
    re, im = _call("n", s)
    return float(re), float(im)


def _py_val(re, im):
    return complex(re, im) if im != 0 else re


def _encode_value(v):
    if v is _UnsignedInfinity:
        return "cu"
    if isinstance(v, complex):
        return _call("complex", repr(v.real), repr(v.imag))[0]
    return _call("float", repr(float(v)))[0]


def _complete_special(s):
    """s with each call of a special function at float arguments that Sage
    evaluates at once (gamma(2.5), zeta(2.5 + 1.0*I)) replaced by its value,
    repeatedly, so a call whose argument became a float that way is
    evaluated too (psi(gamma(2.5)))."""
    for _ in range(64):
        rules = []
        for c in _call("special_calls", s, "float"):
            op = _call("operator", c)
            name, args = op[0][4:], op[1:]
            try:
                v = _special_value(name, [_py_val(*_num_pair(t)) for t in args], kinds=False)
            except _AmbiguousPole:
                raise
            except (_Keep, NotImplementedError):
                continue
            rules += [c, _encode_value(v)]
        if not rules:
            break
        s = _call("subs", s, *rules)[0]
    return s


def _lower_special(s):
    """s with every special-function call without symbols replaced by its
    numerical value (for n(): the engine's own numerics stop at them)."""
    if not _SPECIAL_RE.search(s):
        return s
    rules = []
    for c in _call("special_calls", s, "const"):
        op = _call("operator", c)
        name, args = op[0][4:], op[1:]
        vals = [_py_val(*_num_pair(_lower_special(t))) for t in args]
        try:
            v = _special_value(name, vals, kinds=False)
        except _Keep:
            raise ValueError("cannot evaluate %s numerically" % _call("str", c)[0])
        rules += [c, _encode_value(v)]
    return _call("subs", s, *rules)[0] if rules else s


class _Math:
    pass


_M = _Math()
for _k in dir(_m):
    if not _k.startswith("_"):
        setattr(_M, _k, getattr(_m, _k))


def _sgn(v):
    return (v > 0) - (v < 0)


def _undefined(name):
    raise ValueError("cannot evaluate %s numerically" % name)


_FAST_GLOBALS = {"_m": _M, "_gamma": _gamma, "_sp": _sp, "_sgn": _sgn, "_undefined": _undefined,
                 "__builtins__": {"abs": abs, "complex": complex, "float": float}}


# ------------------------------------------------------------------ constructors

_LATEX_NAMES = {}   # symbol name -> LaTeX (var('th', latex_name=r'\theta'))
_LATEX_SYM = {}     # symbol name -> its LaTeX without a latex_name


# ---------------------------------------------------------------- assumptions

_ASSUMPTIONS = []   # relations (x > 0) and _Feature(n, 'integer')


class _Feature:
    """An assumption 'n is integer' made by assume(n, 'integer')."""

    def __init__(self, v, kind):
        self._v, self._kind = v, kind

    def __repr__(self):
        return "%s is %s" % (self._v, self._kind)

    def __eq__(self, o):
        return isinstance(o, _Feature) and str(o._v) == str(self._v) and o._kind == self._kind

    def __hash__(self):
        return hash((str(self._v), self._kind))


def assume(*args):
    """Assume relations (x > 0) or properties (assume(n, 'integer');
    'integer', 'real', 'positive', 'even', 'odd', ...); used by abs,
    sqrt simplification, bool of relations, sin(n*pi) and solve.

    EXAMPLES::

        sage: assume(x > 0); bool(sqrt(x^2) == x), abs(x)
        (True, x)
        sage: assumptions()
        [x > 0]
        sage: forget()
    """
    args = list(args)
    i = 0
    while i < len(args):
        a = args[i]
        if isinstance(a, (list, tuple)):
            assume(*a)
        elif i + 1 < len(args) and isinstance(args[i + 1], str):
            f = _Feature(a, args[i + 1])
            if f not in _ASSUMPTIONS:
                _ASSUMPTIONS.append(f)
            i += 1
        elif isinstance(a, Expression) and a.is_relational():
            if not any(isinstance(r, Expression) and str(r) == str(a) for r in _ASSUMPTIONS):
                _ASSUMPTIONS.append(a)
        elif a is True or a is False:
            pass
        else:
            raise TypeError("assume(relation) or assume(variable, property)")
        i += 1


def forget(*args):
    """Forget the given assumptions, or all of them.

    EXAMPLES::

        sage: assume(x > 0); forget(x > 0); assumptions()
        []
    """
    if not args:
        del _ASSUMPTIONS[:]
        return
    args = list(args)
    i = 0
    while i < len(args):
        a = args[i]
        if i + 1 < len(args) and isinstance(args[i + 1], str):
            f = _Feature(a, args[i + 1])
            if f in _ASSUMPTIONS:
                _ASSUMPTIONS.remove(f)
            i += 1
        else:
            for r in list(_ASSUMPTIONS):
                if isinstance(r, Expression) and str(r) == str(a):
                    _ASSUMPTIONS.remove(r)
        i += 1


def assumptions(*args):
    """The current assumptions (about the given variables).

    EXAMPLES::

        sage: assume(x > 0, x < 1); assumptions()
        [x > 0, x < 1]
        sage: forget()
    """
    if not args:
        return list(_ASSUMPTIONS)
    names = {str(a) for a in args}
    out = []
    for r in _ASSUMPTIONS:
        vs = {str(r._v)} if isinstance(r, _Feature) else set(r._names())
        if vs & names:
            out.append(r)
    return out


class assuming:
    """A context in which some assumptions hold: with assuming(x > 0): ...

    EXAMPLES::

        sage: with assuming(x > 0):
        ....:     abs(x)
        x
        sage: assumptions()
        []
    """

    def __init__(self, *args, **kw):
        self._args = args
        self._replace = kw.get("replace", False)

    def __enter__(self):
        self._saved = list(_ASSUMPTIONS)
        if self._replace:
            del _ASSUMPTIONS[:]
        assume(*self._args)

    def __exit__(self, *exc):
        _ASSUMPTIONS[:] = self._saved
        return False


def _assume_on(sol, names):
    """A family (or a solution with conditions) under the assumptions on
    the solved variable: each becomes a condition on the solution's value
    (assume(x > 0); sin(x) == 0: x == pi*n1 if pi*n1 > 0); 'integer' and
    the like on such a solution are refused (the review of solve's
    CSOL-F9: the whole family came back).  None if a condition fails."""
    if len(sol) != 1 or not isinstance(sol[0], Solution):
        return sol
    s = sol[0]
    try:
        if s.lhs()._op()[0] != "symbol":
            return sol
    except Exception:
        return sol
    x, v = str(s.lhs()), s.rhs()
    # a numerical value is checked by _satisfies; a symbolic one (x == a,
    # x == r1, a family) gets the assumptions as conditions (CSOL-F9)
    if not v.variables():
        return sol
    extra = []
    for r in _ASSUMPTIONS:
        if isinstance(r, _Feature):
            if str(r._v) != x:
                continue
            if r._kind == "real":
                extra.append(_one("fun", "imag_part", v._s) == 0)
            elif r._kind == "positive":
                extra.append(v > 0)
            elif r._kind == "negative":
                extra.append(v < 0)
            else:
                raise NotImplementedError("solve: the assumption that %s is %s on the symbolic solution %s" % (x, r._kind, s))
        elif isinstance(r, Expression) and x in r._names():
            extra.append(r.subs({s.lhs(): v}))
    if not extra:
        return sol
    keep = list(s._conds)
    for c in extra:
        if not c.variables():
            verdict = _decide(c)
            if verdict is True:
                continue
            if verdict is False:
                return None
        keep.append(c)
    return [Solution(s._s, keep, s._params)]


def _satisfies(sol):
    """Whether a solution [x == a, ...] is compatible with the assumptions
    (the relations that become numerical after substituting it)."""
    sub = {}
    for eq in sol:
        try:
            if eq.lhs()._op()[0] != "symbol":
                continue  # 0 == f: a factor whose roots were not found
            sub[eq.lhs()] = eq.rhs()
        except Exception:
            return True
    for r in _ASSUMPTIONS:
        if isinstance(r, _Feature):
            v = next((w for k, w in sub.items() if str(k) == str(r._v)), None)
            if v is None or v.variables():
                continue
            if r._kind in ("real", "integer", "rational", "even", "odd", "positive", "negative"):
                im = v.imag()
                if _call("is_zero", im._s)[0] != "1" and _const_sign(im) not in (None, 0):
                    return False  # certainly not real
            if r._kind in ("integer", "even", "odd"):
                fl = floor(v)
                if fl.is_numeric() and _const_sign(v - fl) == 1:
                    return False  # certainly not an integer
                q = _py_number(v._s)
                if r._kind in ("even", "odd") and isinstance(q, int):
                    if (q % 2 == 0) != (r._kind == "even"):
                        return False  # the wrong parity (the systematic review's R2-SYMALG-F2)
            if r._kind in ("positive", "negative"):
                sg = _const_sign(v)
                if sg is not None and sg != (1 if r._kind == "positive" else -1):
                    return False
            if r._kind in ("rational", "integer", "even", "odd") and not _is_rational_number(v):
                if _certainly_irrational(v):
                    return False
            continue
        if not isinstance(r, Expression):
            continue
        rr = r.subs(sub)
        if rr.variables():
            continue
        # decided by the engine (bool() of a relation is no proof, and it
        # raised in pyjs, so assume(x > 0) kept x == -1 there)
        if _decide(rr) is False:
            return False
    return True


def _system_assume(sols, names):
    """The solutions [x == ..., y == ..., conditions...] of a system under
    the assumptions, with the whole assignment substituted into each (x > y
    is decided by x and y together, which neither one-variable step can do:
    assume(x > y); [x^2 == 1, y == -x] kept x == -1, y == 1, the review's
    SOLVE2-F6): dropped where one is false, undecided ones kept as
    conditions; a feature (x positive) of a symbolic value becomes a
    condition as for one equation."""
    out = []
    for sol in sols:
        n = len(names)
        assign, extra = list(sol[:n]), list(sol[n:])
        sub = {}
        for s in assign:
            if s._op()[0] == "rel:Eq" and s.lhs()._op()[0] == "symbol":
                sub[str(s.lhs())] = s.rhs()
        if not _satisfies(assign):
            continue
        conds = []
        for r in _ASSUMPTIONS:
            if isinstance(r, _Feature):
                v = sub.get(str(r._v))
                if v is None or not v.variables():
                    continue  # numerical values: _satisfies
                if r._kind == "real":
                    conds.append(_one("fun", "imag_part", v._s) == 0)
                elif r._kind == "positive":
                    conds.append(v > 0)
                elif r._kind == "negative":
                    conds.append(v < 0)
                else:
                    raise NotImplementedError("solve: the assumption that %s is %s on the symbolic solution %s == %s" % (r._v, r._kind, r._v, v))
            elif isinstance(r, Expression) and set(r._names()) & set(sub):
                conds.append(r.subs({Expression(_sym_s(k)): w for k, w in sub.items()}))
        keep, ok = [], True
        for c in conds:
            if not c.variables():
                verdict = _decide(c)
                if verdict is True:
                    continue
                if verdict is False:
                    ok = False
                    break
            if not any(str(c) == str(e) for e in keep + extra):
                keep.append(c)
        if ok:
            out.append(assign + extra + keep)
    return out


def _is_rational_number(v):
    q = _py_number(v._s)
    return q is not None and not isinstance(q, float) and not isinstance(q, complex)


def _certainly_irrational(v):
    """Whether the constant v is an algebraic number of degree > 1 (sqrt(2)):
    exactly, through QQbar; False when that is not established."""
    try:
        import _sage_qqbar
        a = _sage_qqbar._from_expr(v)
        return a is not None and a._gen is not None and a.degree() > 1
    except Exception:
        return False


def _integer_multiple_of_pi(arg):
    """k when arg = k*pi with k an integer combination of products of
    integer-assumed symbols, else None."""
    q = (arg / pi).expand()
    names = q._names()
    ints = {n for n in names if _features(n) & {"integer", "even", "odd"}}
    if not names or set(names) != ints:
        return None
    for t in (q.operands() if q._op()[0] == "add" else [q]):
        for f in (t.operands() if t._op()[0] == "mul" else [t]):
            tag = f._op()[0]
            if tag == "symbol":
                continue
            if tag == "pow" and f.operands()[0]._op()[0] == "symbol":
                try:
                    if int(f.operands()[1]) > 0:
                        continue
                except (TypeError, ValueError):
                    pass
                return None
            v = _py_number(f._s)
            if v is None or isinstance(v, float) or getattr(v, "denominator", 1) != 1:
                return None
    return q


def _features(v):
    return {r._kind for r in _ASSUMPTIONS if isinstance(r, _Feature) and str(r._v) == str(v)}


def _sign_of(e):
    """+1 (or 0 allowed) / -1 when the assumptions make e positive /
    negative (e a symbol, or a product/power of such), else None."""
    if not _ASSUMPTIONS:
        return None
    t = e._op()[0]
    if t == "symbol":
        name = str(e)
        if "positive" in _features(name):
            return 1
        for r in _ASSUMPTIONS:
            if not isinstance(r, Expression):
                continue
            k = r._op()[0][4:]
            a, b = r.lhs(), r.rhs()
            sym_a, sym_b = str(a) == name, str(b) == name
            # the bound's certified sign (float(-10^-400) is -0.0, which is
            # >= 0: x > -10^-400 made x positive, the systematic review's
            # R2-SYMALG-F2)
            try:
                if sym_a and b.is_numeric():
                    c = _const_sign(b)
                    if k in ("Gt", "Ge") and c in (0, 1):
                        return 1
                    if k in ("Lt", "Le") and c in (0, -1):
                        return -1
                if sym_b and a.is_numeric():
                    c = _const_sign(a)
                    if k in ("Lt", "Le") and c in (0, 1):
                        return 1
                    if k in ("Gt", "Ge") and c in (0, -1):
                        return -1
            except (TypeError, ValueError):
                pass
        return None
    if t == "mul":
        sg = 1
        for f in e.operands():
            if f.is_numeric():
                c = _const_sign(f)
                if c is None or c == 0:
                    return None
                sg *= c
                continue
            s1 = _sign_of(f)
            if s1 is None:
                return None
            sg *= s1
        return sg
    if t == "pow":
        b, x = e.operands()
        sb = _sign_of(b)
        if sb is None:
            return None
        if sb > 0:
            # b^x > 0 needs a real exponent (x^I has modulus 1, not x^I)
            return 1 if _is_real(x) else None
        # a negative base: only an integer exponent has a sign (int(1/2) is
        # 0: sqrt(x) for x < 0 counted as positive, abs(sqrt(-1)) was I)
        k = _py_number(x._s)
        if isinstance(k, int) or (getattr(k, "denominator", None) == 1 and not isinstance(k, float)):
            return 1 if int(k) % 2 == 0 else -1
        return None
    if e.is_numeric():
        c = _const_sign(e)
        if c is not None:
            return 1 if c >= 0 else -1
    return None


def _const_sign(e):
    """The certified sign of a real constant (1, 0, -1), or None."""
    r = _call("const_sign", e._s)[0]
    return int(r) if r else None


def _is_real(e):
    """Whether e is certainly real: a real constant, or a symbol assumed
    real (or integer, positive, ..., or bounded by a relation)."""
    if e.is_numeric():
        try:
            return _call("is_zero", e.imag()._s)[0] == "1"
        except Exception:
            return False
    if e._op()[0] == "symbol":
        name = str(e)
        if _features(name) & {"real", "integer", "rational", "even", "odd", "positive", "negative"}:
            return True
        # a relation makes real its two sides, not each symbol in them (a + b
        # > 0 says nothing of a alone)
        def real_side(r):
            if not (isinstance(r, Expression) and r._op()[0][4:] in ("Lt", "Le", "Gt", "Ge")):
                return False
            lhs, rhs = r.lhs(), r.rhs()
            return (str(lhs) == name and not rhs.variables() and _is_real(rhs)) or (str(rhs) == name and not lhs.variables() and _is_real(lhs))
        return any(real_side(r) for r in _ASSUMPTIONS)
    return False


def _assume_rewrite(e):
    """e simplified with the assumptions: sqrt(x^2) = x and abs(x) = x for
    x > 0 (products and powers of such too)."""
    t = e._op()[0]
    if t in ("symbol", "rational", "integer", "constant") or not e.operands():
        return e
    ops = [_assume_rewrite(a) for a in e.operands()]
    if t == "add":
        return sum(ops, Expression(_call("parse", "0")[0]))
    if t == "mul":
        r = _expr(1)
        for a in ops:
            r = r * a
        return r
    if t == "pow":
        b, x = ops
        try:
            k = _py_number(x._s)
        except Exception:
            k = None
        if k is not None and not isinstance(k, float) and getattr(k, "denominator", 1) == 2:
            # (b)^(m/2): b = c^2 with c of known sign
            bt = b._op()[0]
            if bt == "pow":
                c, y = b.operands()
                try:
                    yk = int(y)
                except (TypeError, ValueError):
                    yk = None
                if yk is not None and yk % 2 == 0 and _sign_of(c) == 1:
                    return c ** (yk // 2 * 2 * k)
        return b ** x
    if t == "fun:abs":
        sg = _sign_of(ops[0])
        if sg is not None:
            return ops[0] if sg >= 0 else -ops[0]
    return e


def var(*names, **kw):
    """var('x y') or var('x', 'y'): symbolic variables, also defined in __main__.

    EXAMPLES::

        sage: var('a b c')
        (a, b, c)
        sage: a + b + c
        a + b + c
    """
    if len(names) == 1 and isinstance(names[0], (list, tuple)):
        names = tuple(names[0])
    if len(names) == 1 and isinstance(names[0], str):
        names = names[0].replace(",", " ").split()
    for n in names:
        if not n.isidentifier():
            raise ValueError("The name \"%s\" is not a valid Python identifier." % n)
    vs = tuple(Expression(_sym_s(n)) for n in names)
    if kw.get("latex_name") is not None:
        for n in names:
            _LATEX_NAMES[n] = str(kw["latex_name"])
    if kw.get("domain") in ("positive", "integer", "real", "complex"):
        for v in vs:
            assume(v, kw["domain"])
    import sys
    main = sys.modules.get("__main__")
    if main is not None:
        for n, v in zip(names, vs):
            setattr(main, n, v)
    return vs[0] if len(vs) == 1 else vs


def _numeric_arg(a):
    return isinstance(a, float) or (isinstance(a, complex) and not isinstance(a, bool))


_RealNumber = _RealBig = None


def _rr_args(args):
    """0 when no argument is an element of RR (a RealNumber) or one is
    complex, 2 when one is past the doubles (an _RealBig), else 1 (a loop,
    with isinstance tests only: the normal path of every function call goes
    through here)."""
    global _RealNumber, _RealBig
    if _RealNumber is None:
        from _sage_lang import RealNumber as _RealNumber, _RealBig
    k = 0
    for a in args:
        if isinstance(a, _RealNumber):
            if isinstance(a, _RealBig):
                k = 2
            elif k == 0:
                k = 1
        elif isinstance(a, complex):
            return 0
    return k


def _rr_exact(r, fl):
    """Whether the double r = f(*fl) is RR's value: r is a normal double or
    NaN, or an argument is a zero, an infinity or NaN (where the functions
    are exact).  Otherwise (an overflow, an underflow, a subnormal value)
    RR's value is past the doubles."""
    return r != r or _NORMAL_MIN < abs(r) < _INF or any(t == 0 or t != t or t in (_INF, -_INF) for t in fl)


_NORMAL_MIN, _INF = 2.2250738585072014e-308, float("inf")
_RR_WIDE = None


def _rr_wide(v):
    """v in a 117-bit real field: an identity (arccot(x) = arctan(1/x)) is
    evaluated there and rounded once to 53 bits."""
    global _RR_WIDE
    if _RR_WIDE is None:
        import _sage_real
        _RR_WIDE = _sage_real.RealField_(117, "RNDN")
    return _RR_WIDE(v)


# RR's functions past the doubles, in the 53-bit MP field (lib/_sage_real.py:
# correctly rounded), or by an identity at 117 bits rounded once
_RR_MP_FUNCTIONS = {n: (lambda v, n=n: getattr(v, n)()) for n in (
    "sin", "cos", "tan", "cot", "sec", "csc", "arcsin", "arccos", "arctan", "sinh", "cosh", "tanh",
    "arcsinh", "arccosh", "arctanh", "exp", "log")}
_RR_MP_FUNCTIONS.update({
    "arccot": lambda v: (1 / _rr_wide(v)).arctan(),
    "arcsec": lambda v: (1 / _rr_wide(v)).arccos(),
    "arccsc": lambda v: (1 / _rr_wide(v)).arcsin(),
    "coth": lambda v: 1 / _rr_wide(v).tanh(),
    "sech": lambda v: 1 / _rr_wide(v).cosh(),
    "csch": lambda v: 1 / _rr_wide(v).sinh()})


def _rr_function(name, args, numeric):
    """name(*args) in RR where the double result is not RR's value (an
    argument or the value is past the doubles): computed in the MP field,
    or NotImplementedError, never a double's infinity or zero."""
    import _sage_lang
    if len(args) == 1:
        x = args[0]
        if name in ("sgn", "heaviside"):
            return numeric(x)  # (comparisons only, exact)
        if name in ("floor", "ceil"):
            return getattr(x, name)()
        if name == "log" and x < 0:
            # log|x| + pi I: log|x| is a double for every element of RR
            from _sage_matrix import ComplexNumber
            return ComplexNumber(float(_sage_lang._rr_from_mp(_sage_lang._rr_operand(-x).log())), _m.pi)
        g = _RR_MP_FUNCTIONS.get(name)
        if g is not None and x == x:
            v = g(_sage_lang._rr_operand(x))
            # (outside the real domain the value is complex, as in Sage)
            if v._special != "nan":
                return _sage_lang._rr_from_mp(v)
    raise NotImplementedError("%s(%s): the value in RR, past the double range, is not available in sagebrush yet"
                              % (name, ", ".join(map(str, args))))


def _function(name, numeric=None, cnumeric=None):
    """A Sage function: numerical on floats, exact or symbolic otherwise
    (sin(0) = 0, sin(pi/6) = 1/2, sin(1) stays sin(1))."""
    def f(*args, **kw):
        if args and all(_numeric_arg(a) or isinstance(a, int) for a in args) and any(_numeric_arg(a) for a in args):
            if numeric is not None and not any(isinstance(a, complex) for a in args):
                # RR's elements past the doubles (an _RealBig), and values
                # past them, are computed in the MP field
                rr = _rr_args(args)
                if rr == 2:
                    return _rr_function(name, args, numeric)
                fl = [float(a) for a in args]
                try:
                    r = numeric(*fl)
                except OverflowError:
                    if rr:
                        return _rr_function(name, args, numeric)
                except ValueError:
                    pass
                else:
                    if not isinstance(r, float):
                        return r
                    if rr and not _rr_exact(r, fl) and name not in ("sgn", "heaviside"):
                        return _rr_function(name, args, numeric)
                    return _RealNumber(r)
            r = _one("fun", name, *[_to_s(a) for a in args]).n()
            return r
        try:
            ss = [_expr(a)._s for a in args]
        except TypeError:
            h = getattr(args[0], name, None) if args else None
            if h is not None:
                return h()
            raise
        r = Expression(_call("fun", name, *ss)[0])
        if _ASSUMPTIONS and name in ("sin", "cos", "tan") and len(args) == 1 and r._op()[0] == "fun:" + name:
            k = _integer_multiple_of_pi(_expr(args[0]))
            if k is not None:
                return _expr(0) if name != "cos" else (-1) ** k
        if all(not isinstance(a, Expression) and not _is_poly(a) for a in args):
            v = _py_number(r._s)
            if v is not None:
                return v
        return r
    f.__name__ = name
    return f



def _rr_special_exact(name, v, fl):
    """Whether the double v = name(*fl) is RR's value: v is a normal double
    or NaN, an argument is a zero, an infinity or NaN, v is the infinity of
    a pole, or a trivial zero of zeta.  Otherwise (an overflow, an
    underflow, a subnormal value) RR's value is past the doubles."""
    if _rr_exact(v, fl):
        return True
    if v in (_INF, -_INF):
        return _is_pole(name, fl) or (name == "erfinv" and abs(fl[0]) == 1)
    return v == 0 and name in ("zeta", "hurwitz_zeta") and fl[0] < 0 and fl[0] % 2 == 0 \
        and (name == "zeta" or fl[1] == 1)


def _rr_special(name, args):
    """name(*args) in RR past the doubles: gamma and log_gamma in the MP
    field; the other special functions raise NotImplementedError (never a
    double's overflowed infinity or underflowed zero)."""
    import _sage_lang
    if name in ("gamma", "log_gamma") and len(args) == 1 and not (name == "log_gamma" and args[0] < 0):
        return _sage_lang._rr_from_mp(getattr(_sage_lang._rr_operand(args[0]), name)())
    raise NotImplementedError("%s(%s): the value in RR, past the double range, is not available in sagebrush yet"
                              % (name, ", ".join(map(str, args))))


def _special_function(name, nargs=(1,)):
    """A Sage special function (engine/sym special.rs for exact values and
    derivatives, lib/_special.py for numerical ones): a number at Python
    floats and complexes where Sage evaluates there, else an expression
    (whose float calls the engine leaves to _complete_special)."""
    def f(*args):
        if len(args) not in nargs:
            raise TypeError("%s() takes %s arguments (%d given)" % (name, " or ".join(map(str, nargs)), len(args)))
        if all(_numeric_arg(a) or isinstance(a, int) for a in args) and any(_numeric_arg(a) for a in args) \
                and not (name == "psi" and len(args) == 2) and name != "zetaderiv":
            rr = _rr_args(args)
            if rr == 2:
                return _rr_special(name, args)
            fl = [complex(a) if isinstance(a, complex) else float(a) for a in args]
            try:
                v = _special_value(name, fl)
            except _Keep:
                v = None
            if rr and type(v) is float and not _NORMAL_MIN < abs(v) < _INF and not _rr_special_exact(name, v, fl):
                return _rr_special(name, args)
            if v is _UnsignedInfinity:
                return Expression("cu")
            if v is not None:
                if isinstance(v, complex):
                    from _sage_matrix import ComplexNumber
                    return ComplexNumber(v.real, v.imag)
                from _sage_lang import RealNumber
                return RealNumber(v)
        r = Expression(_call("fun", name, *[_expr(a)._s for a in args])[0])
        if all(not isinstance(a, Expression) and not _is_poly(a) for a in args):
            v = _py_number(r._s)
            if v is not None:
                return v
        return r
    f.__name__ = name
    return f

