        try:
            return self(int(x))
        except Exception:
            raise TypeError("unable to convert %r to an element of %r" % (x, self))

    def zero(self):
        """0.

        EXAMPLES::

            sage: GF(5).zero(), Integers(8).one()
            (0, 1)
        """
        return _elt(self, 0)

    def one(self):
        """1.

        EXAMPLES::

            sage: GF(5).one()
            1
        """
        return _elt(self, 1 % self._n)

    def gen(self, i=0):
        """The generator 1 (as Sage, for Z/nZ).

        EXAMPLES::

            sage: GF(7).gen(), Integers(12).gen()
            (1, 1)
        """
        return self.one()

    def gens(self):
        """(1,).

        EXAMPLES::

            sage: GF(7).gens()
            (1,)
        """
        return (self.one(),)

    def _first_ngens(self, k):
        return self.gens()[:k]

    def __iter__(self):
        for v in range(self._n):
            yield _elt(self, v)

    def list(self):
