def _atomic_num(s):
    # (a leading minus sign is fine: -1/x^2)
    return "+" not in s[1:] and "-" not in s[1:]


def _atomic_den(s):
    return not any(c in s[1:] for c in "+-*/")


class FractionFieldElement:
    """A quotient of polynomials in lowest terms, the denominator monic.

