def _inverse_mod(a, m):
    """a^-1 modulo m (extended Euclid: s_i a = r_i mod m)."""
    R = a.parent()
    r0, r1 = m, a % m
    s0, s1 = R(0), R(1)
    while r1:
        q, r = r0.quo_rem(r1)
        r0, r1 = r1, r
        s0, s1 = s1, s0 - q * s1
    if r0.degree() > 0:
        raise ZeroDivisionError("not invertible")
    c = r0.leading_coefficient()
    return (s0 * (1 / _F(c) if isinstance(c, (int, _F)) else 1 / c)) % m


