        EXAMPLES::

            sage: CDF.real_double_field()
            Real Double Field
        """
        return RDF


def _logabs(x, y):
    """log |x + iy| as GSL computes it."""
    xa, ya = abs(x), abs(y)
    if xa >= ya:
        mx, u = xa, (ya / xa if xa else 0.0)
    else:
        mx, u = ya, xa / ya
    return math.log(mx) + 0.5 * math.log1p(u * u)


class ComplexDoubleElement:
