            sage: CDF(1, 1).cos()
            0.8337300251311491 - 0.9888977057628651*I
        """
        return ComplexDoubleElement._of(cmath.cos(self._z))

    def n(self, prec=None, digits=None):
        """A numerical approximation in CC or ComplexField(prec).

