        if rnd == "RNDN":
            c = 2 * r - D
            if c > 0 or (c == 0 and q & 1):
                q += 1
        elif rnd == "RNDU":
            if not neg:
                q += 1
        elif rnd == "RNDD":
            if neg:
                q += 1
        elif rnd == "RNDA":
            q += 1
