        EXAMPLES::

            sage: cube().rotate((0, 0, 1), pi/4)  # sagebrush only
            Graphics3d Object
        """
        a = _norm(tuple(float(t) for t in v))
        c, s = math.cos(float(theta)), math.sin(float(theta))

        def T(p):
            d = _dot(a, p)
            w = _cross(a, p)
            return tuple(p[i] * c + w[i] * s + a[i] * d * (1 - c) for i in range(3))
        return self._map(T)

    def rotateX(self, theta):
